INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-000000000005', 'global', NULL, 'Barbell Bench Press', 'barbell bench press', 'free_exercise_db', 'A compound strength exercise using a barbell that mainly works the chest, with the front delts and triceps assisting.', 'ai_authored:facts_template', '1. Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.
2. From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.
3. After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again.
4. Repeat the movement for the prescribed amount of repetitions.
5. When you are done, place the bar back in the rack.', '["chest"]', '["front_delts","triceps"]', '["barbell","bench"]', 'beginner', 'active', 'bench-press-barbell', 'strength', 'horizontal_push', 'reps_weight', 'gym', 'compound', 'push', 'bilateral', 'Use a spotter or safety arms for heavy pressing.', 'free_exercise_db', 'Barbell_Bench_Press_-_Medium_Grip', 'Barbell Bench Press - Medium Grip', 'needs_human', 'https://www.youtube.com/results?search_query=Barbell+Bench+Press+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Barbell_Bench_Press_-_Medium_Grip.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:specific', 1, '["csv_disagrees"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-000000000005'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-000000000011', 'global', NULL, 'Barbell Curl', 'barbell curl', 'free_exercise_db', 'An isolation strength exercise using a barbell that mainly works the biceps, with the forearms assisting.', 'ai_authored:facts_template', '1. Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.
2. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out.
3. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.
4. Slowly begin to bring the bar back to starting position as your breathe in.
5. Repeat for the recommended amount of repetitions.', '["biceps"]', '["forearms"]', '["barbell"]', 'beginner', 'active', 'barbell-curl', 'strength', 'elbow_flexion', 'reps_weight', 'gym', 'isolation', 'pull', 'bilateral', 'Use a load you can control for the whole set.', 'free_exercise_db', 'Barbell_Curl', 'Barbell Curl', 'approve', 'https://www.youtube.com/results?search_query=Barbell+Curl+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Barbell_Curl.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:specific', 0, '[]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-000000000011'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-000000000004', 'global', NULL, 'Barbell Deadlift', 'barbell deadlift', 'free_exercise_db', 'A compound strength exercise using a barbell that mainly works the lower back, with the calves and forearms assisting.', 'ai_authored:facts_template', '1. Stand in front of a loaded barbell.
2. While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise.
3. While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.
4. Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.
5. Perform the amount of repetitions prescribed in the program.', '["lower_back"]', '["calves","forearms","glutes","hamstrings","lats","upper_back","quads","traps"]', '["barbell"]', 'intermediate', 'active', 'deadlift-barbell', 'strength', 'hinge', 'reps_weight', 'gym', 'compound', 'pull', 'bilateral', 'Start light; stop if you feel sharp lower-back pain.', 'free_exercise_db', 'Barbell_Deadlift', 'Barbell Deadlift', 'approve', 'https://www.youtube.com/results?search_query=Barbell+Deadlift+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Barbell_Deadlift.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:specific', 0, '[]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-000000000004'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-00000000001a', 'global', NULL, 'Barbell Hip Thrust', 'barbell hip thrust', 'free_exercise_db', 'A compound strength exercise using a barbell that mainly works the glutes, with the calves and hamstrings assisting.', 'ai_authored:facts_template', '1. Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs.
2. Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.
3. Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.', '["glutes"]', '["calves","hamstrings"]', '["barbell"]', 'intermediate', 'active', 'barbell-hip-thrust', 'strength', 'hinge', 'reps_weight', 'gym', 'compound', 'push', 'bilateral', 'Start light; stop if you feel sharp lower-back pain.', 'free_exercise_db', 'Barbell_Hip_Thrust', 'Barbell Hip Thrust', 'needs_human', 'https://www.youtube.com/results?search_query=Barbell+Hip+Thrust+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Barbell_Hip_Thrust.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed; curated edit to pass step validation (curation/steps_source_fixes.tsv)"}', 0, 'ai_authored:specific', 1, '["csv_disagrees","no_drawing","no_image"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-00000000001a'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-000000000001', 'global', NULL, 'Barbell Squat', 'barbell squat', 'free_exercise_db', 'A compound strength exercise using a barbell that mainly works the quads, with the calves and glutes assisting.', 'ai_authored:facts_template', '1. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.
2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.
3. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back.
4. Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.
5. Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.
6. Repeat for the recommended amount of repetitions.', '["quads"]', '["calves","glutes","hamstrings","lower_back"]', '["barbell"]', 'beginner', 'active', 'back-squat-barbell', 'strength', 'squat', 'reps_weight', 'gym', 'compound', 'push', 'bilateral', 'Use safety pins/spotter for heavy barbell work; stop if you feel knee or back pain.', 'free_exercise_db', 'Barbell_Squat', 'Barbell Squat', 'needs_human', 'https://www.youtube.com/results?search_query=Barbell+Squat+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Barbell_Squat.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed; curated edit to pass step validation (curation/steps_source_fixes.tsv)"}', 0, 'ai_authored:specific', 1, '["csv_disagrees"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-000000000001'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-00000000000e', 'global', NULL, 'Bent-Over Barbell Row', 'bent-over barbell row', 'free_exercise_db', 'A compound strength exercise using a barbell that mainly works the upper back, with the biceps and lats assisting.', 'ai_authored:facts_template', '1. Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.
2. Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.
3. Then inhale and slowly lower the barbell back to the starting position.
4. Repeat for the recommended amount of repetitions.', '["upper_back"]', '["biceps","lats","front_delts"]', '["barbell"]', 'beginner', 'active', 'bent-over-row-barbell', 'strength', 'horizontal_pull', 'reps_weight', 'gym', 'compound', 'pull', 'bilateral', 'Keep a neutral spine, especially in bent-over rows.', 'free_exercise_db', 'Bent_Over_Barbell_Row', 'Bent Over Barbell Row', 'approve', 'https://www.youtube.com/results?search_query=Bent-Over+Barbell+Row+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Bent_Over_Barbell_Row.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:specific', 0, '["media_new_everkinetic_match","no_drawing","no_image"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-00000000000e'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-00000000001d', 'global', NULL, 'Bird Dog', 'bird dog', 'library', 'A compound strength exercise using your bodyweight that mainly works the abs and lower back, with the glutes and rear shoulders assisting.', 'ai_authored:fitbud_curated', '1. Start on your hands and knees with your hands under your shoulders and knees under your hips.
2. Brace your core to keep your back flat.
3. Reach one arm forward and the opposite leg back until both are straight.
4. Hold for a second, return, and switch sides.', '["abs","lower_back"]', '["glutes","rear_delts"]', '["bodyweight","mat"]', 'beginner', 'active', 'bird-dog', 'strength', 'core_anti_extension', 'reps_bodyweight', 'home', 'compound', 'static', 'alternating', 'Stop when form breaks rather than chasing time.', 'fitbud', 'bird_dog', 'Bird dog', 'needs_human', 'https://www.youtube.com/results?search_query=Bird+Dog+exercise+form', 'fitbud_written', '{"licence":"FitBud proprietary (own wording)","author":"FitBud"}', 1, 'ai_authored:specific', 1, '["ai_authored_steps","no_drawing","no_image","steps_fitbud_written_trainer_review"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-00000000001d'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-000000000014', 'global', NULL, 'Bodyweight Walking Lunge', 'bodyweight walking lunge', 'free_exercise_db', 'A single-side compound strength exercise using your bodyweight that mainly works the quads, with the calves and glutes assisting.', 'ai_authored:facts_template', '1. Stand tall with your feet hip-width apart.
2. Step forward into a long stride and lower your back knee toward the floor.
3. Keep your front shin close to vertical as both knees bend to about 90 degrees.
4. Push through your front foot and step through into the next stride, alternating legs.', '["quads"]', '["calves","glutes","hamstrings"]', '["bodyweight"]', 'beginner', 'active', 'bodyweight-walking-lunge', 'strength', 'lunge', 'reps_bodyweight', 'home', 'compound', 'push', 'unilateral', 'Hold a support for balance if needed; keep loads light until balance is solid.', 'free_exercise_db', 'Bodyweight_Walking_Lunge', 'Bodyweight Walking Lunge', 'approve', 'https://www.youtube.com/results?search_query=Bodyweight+Walking+Lunge+exercise+form', 'fitbud_written', '{"licence":"FitBud proprietary (own wording)","author":"FitBud","replaces":"free_exercise_db"}', 1, 'ai_authored:pattern', 1, '["generic_coaching","media_variant_drawing","no_image","steps_fitbud_written_trainer_review"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-000000000014'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-000000000022', 'global', NULL, 'Cable Crossover', 'cable crossover', 'free_exercise_db', 'An isolation strength exercise using a cable station that mainly works the chest, with the front delts assisting.', 'ai_authored:facts_template', '1. To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.
2. Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.
3. With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement.
4. Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.
5. Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.', '["chest"]', '["front_delts"]', '["cable"]', 'beginner', 'active', 'cable-crossover', 'strength', 'chest_fly', 'reps_weight', 'gym', 'isolation', 'push', 'bilateral', 'Stop short of shoulder discomfort at the bottom.', 'free_exercise_db', 'Cable_Crossover', 'Cable Crossover', 'approve', 'https://www.youtube.com/results?search_query=Cable+Crossover+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Cable_Crossover.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 0, '["generic_coaching","no_alternative"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-000000000022'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('e1000001-0000-4000-8000-00000000001c', 'global', NULL, 'Dead Bug', 'dead bug', 'free_exercise_db', 'A compound strength exercise using your bodyweight that mainly works the abs.', 'ai_authored:facts_template', '1. Begin lying on your back with your hands extended above you toward the ceiling.
2. Bring your feet, knees, and hips up to 90 degrees.
3. Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position. Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.
4. Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.
5. Stay tight and return the working leg to the starting position.
6. Repeat on the opposite side, alternating until the set is complete.', '["abs"]', '[]', '["bodyweight"]', 'beginner', 'active', 'dead-bug', 'strength', 'core_anti_extension', 'reps_bodyweight', 'home', 'compound', 'pull', 'bilateral', 'Stop when form breaks rather than chasing time.', 'free_exercise_db', 'Dead_Bug', 'Dead Bug', 'needs_human', 'https://www.youtube.com/results?search_query=Dead+Bug+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Dead_Bug.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:specific', 1, '["csv_disagrees","no_drawing","no_image"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'e1000001-0000-4000-8000-00000000001c'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
