INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('f38bb441-e520-5c9a-9876-6f1e8ec00a15', 'global', NULL, 'Butterfly', 'butterfly', 'free_exercise_db', 'An isolation strength exercise using the machine that mainly works the chest.', 'ai_authored:facts_template', '1. Sit on the machine with your back flat on the pad.
2. Take hold of the handles. This will be your starting position.
3. Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.
4. Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.
5. Repeat for the recommended amount of repetitions.', '["chest"]', '[]', '["machine"]', 'beginner', 'active', 'butterfly', 'strength', 'chest_fly', 'reps_weight', 'gym', 'isolation', 'pull', 'bilateral', 'Stop short of shoulder discomfort at the bottom.', 'free_exercise_db', 'Butterfly', 'Butterfly', 'approve', 'https://www.youtube.com/results?search_query=Butterfly+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Butterfly.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 0, '["generic_coaching","no_alternative","no_image"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'f38bb441-e520-5c9a-9876-6f1e8ec00a15'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('23036416-1381-5905-9972-cda4e784c8b6', 'global', NULL, 'Cable Chest Press', 'cable chest press', 'free_exercise_db', 'A compound strength exercise using a cable station that mainly works the chest, with the front delts and triceps assisting.', 'ai_authored:facts_template', '1. Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.
2. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.
3. After pausing at full extension, return to th starting position, keeping tension on the cables.
4. You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.', '["chest"]', '["front_delts","triceps"]', '["cable"]', 'beginner', 'active', 'cable-chest-press', 'strength', 'horizontal_push', 'reps_weight', 'gym', 'compound', 'push', 'bilateral', 'Use a spotter or safety arms for heavy pressing.', 'free_exercise_db', 'Cable_Chest_Press', 'Cable Chest Press', 'approve', 'https://www.youtube.com/results?search_query=Cable+Chest+Press+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Cable_Chest_Press.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 0, '["generic_coaching","no_drawing","no_image"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '23036416-1381-5905-9972-cda4e784c8b6'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('4e120edc-ea39-5f74-9757-94cfc391cf4b', 'global', NULL, 'Cable Crunch', 'cable crunch', 'free_exercise_db', 'An isolation strength exercise using a cable station that mainly works the abs.', 'ai_authored:facts_template', '1. Kneel below a high pulley that contains a rope attachment.
2. Grasp cable rope attachment and lower the rope until your hands are placed next to your face.
3. Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.
4. With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.
5. Slowly return to the starting position as you inhale. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.
6. Repeat for the recommended amount of repetitions.', '["abs"]', '[]', '["cable"]', 'beginner', 'active', 'cable-crunch', 'strength', 'core_flexion', 'reps_weight', 'gym', 'isolation', 'pull', 'bilateral', 'Skip or modify if it aggravates lower-back pain.', 'free_exercise_db', 'Cable_Crunch', 'Cable Crunch', 'approve', 'https://www.youtube.com/results?search_query=Cable+Crunch+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Cable_Crunch.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 0, '["generic_coaching","no_drawing","no_image"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '4e120edc-ea39-5f74-9757-94cfc391cf4b'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
