INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('96cff86c-5194-5359-9aba-bb35b49a77c7', 'global', NULL, 'Cable Hip Adduction', 'cable hip adduction', 'free_exercise_db', 'An isolation strength exercise using a cable station that mainly works the quads.', 'ai_authored:facts_template', '1. Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.
2. Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.
3. Now step out and away from the stack with a wide stance and grasp the bar of the pulley system. Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.
4. Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.
5. Slowly return to the starting position as you breathe in.
6. Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.', '["quads"]', '[]', '["cable"]', 'beginner', 'active', 'cable-hip-adduction', 'strength', 'hip_abduction_adduction', 'reps_weight', 'gym', 'isolation', 'pull', 'bilateral', 'Stay within a pain-free range.', 'free_exercise_db', 'Cable_Hip_Adduction', 'Cable Hip Adduction', 'approve_with_flags', 'https://www.youtube.com/results?search_query=Cable+Hip+Adduction+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Cable_Hip_Adduction.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 1, '["generic_coaching","no_alternative","no_relations"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '96cff86c-5194-5359-9aba-bb35b49a77c7'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
