INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('a77b3d7a-9c90-55d9-a33a-7ceb5425acd2', 'global', NULL, 'Chin-up', 'chin-up', 'free_exercise_db', 'A compound strength exercise using a pull-up bar that mainly works the lats, with the biceps and forearms assisting.', 'ai_authored:facts_template', '1. Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.
2. As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position.
3. As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. The forearms should do no other work other than hold the bar.
4. After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.
5. Repeat this motion for the prescribed amount of repetitions.', '["lats"]', '["biceps","forearms","upper_back"]', '["pull_up_bar"]', 'beginner', 'active', 'chin-up', 'strength', 'vertical_pull', 'reps_bodyweight', 'gym', 'compound', 'pull', 'bilateral', 'Use assistance (band/machine) until you can do clean reps.', 'free_exercise_db', 'Chin-Up', 'Chin-Up', 'approve', 'https://www.youtube.com/results?search_query=Chin-up+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Chin-Up.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 0, '["generic_coaching","media_new_everkinetic_match","no_alternative","no_image"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'a77b3d7a-9c90-55d9-a33a-7ceb5425acd2'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('a6bbc179-22aa-5783-a794-d24691fa136c', 'global', NULL, 'Clock Push-up', 'clock push-up', 'free_exercise_db', 'A compound strength exercise using your bodyweight that mainly works the chest, with the front delts and triceps assisting.', 'ai_authored:facts_template', '1. Move into a prone position on the floor, supporting your weight on your hands and toes.
2. Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.
3. Descend by flexing at the elbow, lowering your chest toward the ground.
4. At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.
5. As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.
6. Return to the starting position and repeat the exercise, working all the way around until you are back where you started.', '["chest"]', '["front_delts","triceps"]', '["bodyweight"]', 'intermediate', 'active', 'clock-push-up', 'strength', 'horizontal_push', 'reps_bodyweight', 'home', 'compound', 'push', 'bilateral', 'Use a spotter or safety arms for heavy pressing.', 'free_exercise_db', 'Clock_Push-Up', 'Clock Push-Up', 'approve', 'https://www.youtube.com/results?search_query=Clock+Push-up+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Clock_Push-Up.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 1, '["generic_coaching","media_variant_drawing","no_image"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'a6bbc179-22aa-5783-a794-d24691fa136c'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('0af699a7-90ad-5aa2-9224-71e99df54b25', 'global', NULL, 'Close-Grip Barbell Bench Press', 'close-grip barbell bench press', 'free_exercise_db', 'A compound strength exercise using a barbell that mainly works the triceps, with the chest and front delts assisting.', 'ai_authored:facts_template', '1. Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.
2. As you breathe in, come down slowly until you feel the bar on your middle chest.
3. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again.
4. Repeat the movement for the prescribed amount of repetitions.
5. When you are done, place the bar back in the rack.', '["triceps"]', '["chest","front_delts"]', '["barbell","bench"]', 'beginner', 'active', 'close-grip-barbell-bench-press', 'strength', 'horizontal_push', 'reps_weight', 'gym', 'compound', 'push', 'bilateral', 'Use a spotter or safety arms for heavy pressing.', 'free_exercise_db', 'Close-Grip_Barbell_Bench_Press', 'Close-Grip Barbell Bench Press', 'approve', 'https://www.youtube.com/results?search_query=Close-Grip+Barbell+Bench+Press+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Close-Grip_Barbell_Bench_Press.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 0, '["generic_coaching"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '0af699a7-90ad-5aa2-9224-71e99df54b25'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
