INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('df93181c-5b1f-539d-9208-d9b4c8e96d9f', 'global', NULL, 'Exercise Ball Crunch', 'exercise ball crunch', 'free_exercise_db', 'An isolation strength exercise using an exercise ball that mainly works the abs.', 'ai_authored:facts_template', '1. Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).
2. Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.
3. With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.
4. As you inhale, go back to the starting position.
5. Repeat for the recommended amount of repetitions.', '["abs"]', '[]', '["exercise_ball"]', 'beginner', 'active', 'exercise-ball-crunch', 'strength', 'core_flexion', 'reps_weight', 'gym', 'isolation', 'pull', 'bilateral', 'Skip or modify if it aggravates lower-back pain.', 'free_exercise_db', 'Exercise_Ball_Crunch', 'Exercise Ball Crunch', 'needs_human', 'https://www.youtube.com/results?search_query=Exercise+Ball+Crunch+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Exercise_Ball_Crunch.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 1, '["csv_disagrees","generic_coaching","long_step","media_new_everkinetic_match","no_image"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'df93181c-5b1f-539d-9208-d9b4c8e96d9f'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('f225ed9d-de1c-52df-9123-543a269711e2', 'global', NULL, 'Exercise Ball Pull-In', 'exercise ball pull-in', 'free_exercise_db', 'A compound strength exercise using an exercise ball that mainly works the abs.', 'ai_authored:facts_template', '1. Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.
2. Now place your lower shins on top of an exercise ball. This will be your starting position.
3. While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.
4. Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.
5. Repeat for the recommended amount of repetitions.', '["abs"]', '[]', '["exercise_ball"]', 'beginner', 'active', 'exercise-ball-pull-in', 'strength', 'core_flexion', 'reps_weight', 'gym', 'compound', 'pull', 'bilateral', 'Skip or modify if it aggravates lower-back pain.', 'free_exercise_db', 'Exercise_Ball_Pull-In', 'Exercise Ball Pull-In', 'approve', 'https://www.youtube.com/results?search_query=Exercise+Ball+Pull-In+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Exercise_Ball_Pull-In.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 0, '["generic_coaching"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'f225ed9d-de1c-52df-9123-543a269711e2'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
