INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('ec3a9d89-7dab-53cf-b81b-81d701929e20', 'global', NULL, 'Standing Dumbbell Triceps Extension', 'standing dumbbell triceps extension', 'free_exercise_db', 'An isolation strength exercise using dumbbells that mainly works the triceps.', 'ai_authored:facts_template', '1. To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.
2. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.
3. Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Breathe in as you perform this step.
4. Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.
5. Repeat for the recommended amount of repetitions.', '["triceps"]', '[]', '["dumbbell"]', 'beginner', 'active', 'standing-dumbbell-triceps-extension', 'strength', 'elbow_extension', 'reps_weight', 'both', 'isolation', 'push', 'bilateral', 'Reduce range if you feel elbow pain.', 'free_exercise_db', 'Standing_Dumbbell_Triceps_Extension', 'Standing Dumbbell Triceps Extension', 'approve', 'https://www.youtube.com/results?search_query=Standing+Dumbbell+Triceps+Extension+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Standing_Dumbbell_Triceps_Extension.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 0, '["generic_coaching"]', 'library', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'ec3a9d89-7dab-53cf-b81b-81d701929e20'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
