INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('6932a3df-8841-52cc-88e9-c6b80e0142c5', 'global', NULL, 'Sumo Deadlift', 'sumo deadlift', 'free_exercise_db', 'A compound strength exercise using a barbell that mainly works the hamstrings, with the adductors and forearms assisting.', 'ai_authored:facts_template', '1. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.
2. Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.
3. As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.
4. Return the weight to the ground by bending at the hips and controlling the weight on the way down.', '["hamstrings"]', '["adductors","forearms","glutes","lower_back","upper_back","quads","traps"]', '["barbell"]', 'intermediate', 'active', 'sumo-deadlift', 'strength', 'hinge', 'reps_weight', 'gym', 'compound', 'pull', 'bilateral', 'Start light; stop if you feel sharp lower-back pain.', 'free_exercise_db', 'Sumo_Deadlift', 'Sumo Deadlift', 'needs_human', 'https://www.youtube.com/results?search_query=Sumo+Deadlift+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Sumo_Deadlift.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 1, '["csv_disagrees","generic_coaching","no_drawing","no_image"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '6932a3df-8841-52cc-88e9-c6b80e0142c5'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
