INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('8d5d029a-5d93-5581-b979-5d28ca771881', 'global', NULL, 'Tate Press', 'tate press', 'free_exercise_db', 'An isolation strength exercise using dumbbells that mainly works the triceps, with the chest and front delts assisting.', 'ai_authored:facts_template', '1. Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.
2. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Allow your elbows to point out. This is your starting position.
3. Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.
4. As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again.
5. Repeat the movement for the prescribed amount of repetitions of your training program.', '["triceps"]', '["chest","front_delts"]', '["dumbbell"]', 'intermediate', 'active', 'tate-press', 'strength', 'elbow_extension', 'reps_weight', 'both', 'isolation', 'push', 'bilateral', 'Reduce range if you feel elbow pain.', 'free_exercise_db', 'Tate_Press', 'Tate Press', 'needs_human', 'https://www.youtube.com/results?search_query=Tate+Press+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Tate_Press.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_authored:pattern', 1, '["csv_disagrees","generic_coaching"]', 'library+csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '8d5d029a-5d93-5581-b979-5d28ca771881'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
