INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('3e417876-dbb2-5fff-85de-aed1b1ba70da', 'global', NULL, 'Chin-up with Leg Raise', 'chin-up with leg raise', 'user_csv', 'A compound strength exercise with a pull-up bar that mainly works the lats, with the abs and biceps assisting.', 'ai_authored:fitbud_curated', '1. Hang from the pull-up bar with an underhand grip, hands about shoulder-width apart.
2. Pull your chest toward the bar until your chin is over it.
3. Hold the top and raise your straight legs until they are level with your hips.
4. Lower your legs, then lower yourself under control to a full hang.', '["lats"]', '["abs","biceps","shoulders","upper_back"]', '["pull_up_bar"]', 'intermediate', 'active', 'chin-up-with-leg-raise', 'strength', 'vertical_pull', 'reps_bodyweight', 'home', 'compound', 'pull', 'bilateral', 'Use assistance (band/machine) until you can do clean reps.', 'user_csv', 'user_exercises.csv:243', 'Chin Up With Leg Raise', 'approve_with_flags', 'https://www.youtube.com/results?search_query=Chin-up+with+Leg+Raise+exercise+form', 'fitbud_written', '{"licence":"FitBud proprietary (own wording)","author":"FitBud"}', 1, 'ai_derived:pattern', 1, '["no_drawing","steps_fitbud_written_trainer_review"]', 'csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '3e417876-dbb2-5fff-85de-aed1b1ba70da'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('17c2e0f5-2975-596e-a3c0-1a9ac6814c18', 'global', NULL, 'Clean', 'clean', 'free_exercise_db', 'A power exercise using a barbell that mainly works the quads, with the abs and adductors assisting.', 'ai_authored:facts_template', '1. With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.
2. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.
3. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.
4. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.
5. Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.', '["quads"]', '["abs","adductors","biceps","calves","forearms","glutes","hamstrings","lats","lower_back","shoulders","traps","upper_back"]', '["barbell"]', 'intermediate', 'active', 'clean', 'power', 'power', 'reps_weight', 'gym', 'compound', 'pull', 'bilateral', 'Learn with a coach and light loads; power moves are technique-first.', 'user_csv', 'user_exercises.csv:246', 'Clean', 'approve', 'https://www.youtube.com/results?search_query=Clean+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Clean.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_derived:pattern', 0, '["no_drawing"]', 'csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '17c2e0f5-2975-596e-a3c0-1a9ac6814c18'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('321fc63c-60d3-52d1-a3e2-bbdebb708f83', 'global', NULL, 'Clean and Jerk', 'clean and jerk', 'free_exercise_db', 'A power exercise using a barbell that mainly works the quads, with the abs and adductors assisting.', 'ai_authored:facts_template', '1. With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.
2. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.
3. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.
4. Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.
5. The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.
6. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.', '["quads"]', '["abs","adductors","biceps","calves","forearms","glutes","hamstrings","lats","lower_back","shoulders","traps","triceps","upper_back"]', '["barbell"]', 'intermediate', 'active', 'clean-jerk', 'power', 'power', 'reps_weight', 'gym', 'compound', 'pull', 'bilateral', 'Learn with a coach and light loads; power moves are technique-first.', 'user_csv', 'user_exercises.csv:244', 'Clean & Jerk', 'approve', 'https://www.youtube.com/results?search_query=Clean+and+Jerk+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Clean_and_Jerk.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_derived:pattern', 0, '["no_drawing"]', 'csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '321fc63c-60d3-52d1-a3e2-bbdebb708f83'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
