INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('4aad356f-f27f-5021-8463-36680b4ac128', 'global', NULL, 'Close-Grip Lat Pulldown', 'close-grip lat pulldown', 'wger', 'A compound strength exercise with a cable bar that mainly works the lats, with the abs and biceps assisting.', 'ai_authored:fitbud_curated', '1. Sit at the lat pulldown with your thighs secured under the pads.
2. Grip the bar with your hands about shoulder-width apart or slightly closer.
3. Pull the bar down to your upper chest, driving your elbows toward your ribs.
