INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('4b8b0008-4205-5bf3-9323-f5e1573f6a3a', 'global', NULL, 'Single-Arm Chin-up', 'single-arm chin-up', 'free_exercise_db', 'A single-side compound strength exercise using a pull-up bar that mainly works the lats, with the abs and biceps assisting.', 'ai_authored:facts_template', '1. Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.
2. Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.
3. After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.
4. Repeat this motion for the prescribed amount of repetitions.
