INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('19e7b2a7-80e1-5189-a766-7b3fd03ef82d', 'global', NULL, 'Single-Leg Deadlift with Dumbbell', 'single-leg deadlift with dumbbell', 'wger', 'A single-side compound strength exercise using dumbbells that mainly works the hamstrings, with the abs and forearms assisting.', 'ai_authored:facts_template', '1. Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor.
2. Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.
3. Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.
4. Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.
5. After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg.', '["hamstrings"]', '["abs","forearms","glutes","lats","lower_back","upper_back"]', '["dumbbell"]', 'advanced', 'active', 'single-leg-one-dumbbell-deadlift', 'strength', 'hinge', 'reps_weight', 'both', 'compound', 'pull', 'unilateral', 'Start light; stop if you feel sharp lower-back pain.', 'user_csv', 'user_exercises.csv:950', 'Single Leg One Dumbbell Deadlift', 'approve', 'https://www.youtube.com/results?search_query=Single-Leg+Deadlift+with+Dumbbell+exercise+form', 'wger', '{"licence":"CC-BY-SA-4.0","licence_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_url":"https://wger.de/en/exercise/1736/view/","author":"Tierrasverdes","modified":"HTML list converted to ordered steps","share_alike":true}', 0, 'ai_derived:pattern', 0, '["no_drawing"]', 'csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '19e7b2a7-80e1-5189-a766-7b3fd03ef82d'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
