INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('636debea-2b2b-507c-8b81-f13be980e677', 'global', NULL, 'Snatch', 'snatch', 'free_exercise_db', 'A power exercise using a barbell that mainly works the quads, with the abs and adductors assisting.', 'ai_authored:facts_template', '1. Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.
2. With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.
3. Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs. As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.
4. Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.
5. Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.
6. Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead.', '["quads"]', '["abs","adductors","biceps","calves","forearms","glutes","hamstrings","lats","lower_back","shoulders","traps","upper_back"]', '["barbell"]', 'intermediate', 'active', 'snatch', 'power', 'power', 'reps_weight', 'gym', 'compound', 'pull', 'bilateral', 'Learn with a coach and light loads; power moves are technique-first.', 'user_csv', 'user_exercises.csv:1003', 'Snatch', 'approve', 'https://www.youtube.com/results?search_query=Snatch+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Snatch.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_derived:pattern', 0, '["no_drawing"]', 'csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = '636debea-2b2b-507c-8b81-f13be980e677'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('fe218c1f-7d28-545d-8f67-31f57a03eccc', 'global', NULL, 'Snatch Balance', 'snatch balance', 'free_exercise_db', 'A power exercise using a barbell that mainly works the quads, with the abs and adductors assisting.', 'ai_authored:facts_template', '1. Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.
2. Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.
3. Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.
4. Continue to descend to full depth, and return to a standing position. Carefully lower the weight.', '["quads"]', '["abs","adductors","calves","glutes","hamstrings","shoulders","traps","upper_back"]', '["barbell"]', 'intermediate', 'active', 'snatch-balance', 'power', 'power', 'reps_weight', 'gym', 'compound', 'pull', 'bilateral', 'Learn with a coach and light loads; power moves are technique-first.', 'user_csv', 'user_exercises.csv:995', 'Snatch Balance', 'approve', 'https://www.youtube.com/results?search_query=Snatch+Balance+exercise+form', 'free_exercise_db', '{"licence":"Unlicense","licence_url":"https://unlicense.org/","source_url":"https://github.com/yuhonas/free-exercise-db (exercises/Snatch_Balance.json)","author":"free-exercise-db contributors","modified":"split/merged into 3-6 ordered steps; non-instruction sentences removed"}', 0, 'ai_derived:pattern', 0, '["no_drawing"]', 'csv', '2026.10.21-v3', COALESCE((SELECT `created_at` FROM `exercise_library_items` WHERE `id` = 'fe218c1f-7d28-545d-8f67-31f57a03eccc'), '2026-10-20T18:30:00.000Z'), '2026-10-20T18:30:00.000Z');
INSERT OR REPLACE INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `name_norm`, `name_source`, `description`, `description_provenance`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `youtube_search_url`, `steps_source`, `steps_licence_json`, `steps_review_required`, `coaching_provenance`, `needs_human_review`, `review_flags_json`, `origin`, `seed_version`, `created_at`, `updated_at`) VALUES ('c94c1332-69ef-5cc8-bd50-1e49478ca3d5', 'global', NULL, 'Snatch Shrug', 'snatch shrug', 'free_exercise_db', 'A power exercise using a barbell that mainly works the traps, with the abs and adductors assisting.', 'ai_authored:facts_template', '1. Stand tall with your feet about hip-width apart.
2. Hold the barbell in front of your thighs with straight arms, hands in a wide snatch grip.
