-- steps, cues and mistakes: 14037 rows from exercise_library_instructions.sql.
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6ab68577-679a-5d36-99f2-ca7e784b5b5f','e1000001-0000-4000-8000-000000000005','step',1,'Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4c0637b-8f7e-5bf4-b76b-c97f9d9a70ad','e1000001-0000-4000-8000-000000000005','step',2,'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b23102c7-8a30-5d6a-96f8-9f2f0dcb8bad','e1000001-0000-4000-8000-000000000005','step',3,'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f049de70-146a-5914-93e1-38d167d108b0','e1000001-0000-4000-8000-000000000005','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d388af18-85f8-51df-932a-25d275355f7e','e1000001-0000-4000-8000-000000000005','step',5,'When you are done, place the bar back in the rack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bafe0d97-c77d-5fde-90cf-7940f49002dd','e1000001-0000-4000-8000-000000000005','cue',1,'Feet planted, slight arch, shoulder blades pinched','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c850a1ce-e600-5fdf-bfcb-d23e44158cda','e1000001-0000-4000-8000-000000000005','cue',2,'Lower to mid-chest','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7f50f4b8-cdaf-5f01-b64c-df3099178bbc','e1000001-0000-4000-8000-000000000005','cue',3,'Press back over the shoulders','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('db68be93-38bf-5f22-9c60-9db2971ba6e4','e1000001-0000-4000-8000-000000000005','mistake',1,'Bouncing the bar','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3cd0f9f2-28af-5258-9b19-624f05139500','e1000001-0000-4000-8000-000000000005','mistake',2,'Flaring elbows','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('823248f7-7e03-5d12-97a4-46fb809f7924','e1000001-0000-4000-8000-000000000005','mistake',3,'Butt lifting off the bench','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2585d9d7-0e6c-51da-a5e3-6821f01b0227','e1000001-0000-4000-8000-000000000011','step',1,'Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a975319f-3ca6-595b-82f0-73637f95b28a','e1000001-0000-4000-8000-000000000011','step',2,'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c40b0ef-1785-55c5-b588-3bbd97be50f4','e1000001-0000-4000-8000-000000000011','step',3,'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8136085e-7437-57b5-952a-aefeeaa2f0e5','e1000001-0000-4000-8000-000000000011','step',4,'Slowly begin to bring the bar back to starting position as your breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('589ef766-eb85-57f0-994a-98fff3fa60c3','e1000001-0000-4000-8000-000000000011','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('28206c69-7d57-5cde-9e8a-8f30e95e991d','e1000001-0000-4000-8000-000000000011','cue',1,'Elbows by your sides','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bdc3f030-a792-5cd2-a21a-e422f2d2de31','e1000001-0000-4000-8000-000000000011','cue',2,'Curl to shoulder height','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7e6a274d-895a-515c-9c91-b1d066b229b7','e1000001-0000-4000-8000-000000000011','cue',3,'Lower fully','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('acc7e26e-39bd-5c11-b845-bc43e7ad9442','e1000001-0000-4000-8000-000000000011','mistake',1,'Swinging hips','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a52a3858-b3aa-5179-bb1f-27094ba866f8','e1000001-0000-4000-8000-000000000011','mistake',2,'Elbows forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f26e3b93-87da-5335-837a-f3e7eba92651','e1000001-0000-4000-8000-000000000011','mistake',3,'Half reps','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8891bdb9-dfdb-5c6a-b9e6-867431c0f3f6','e1000001-0000-4000-8000-000000000004','step',1,'Stand in front of a loaded barbell.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('93e0b189-134f-5227-a202-7ef859d4d95e','e1000001-0000-4000-8000-000000000004','step',2,'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('af88d26c-1b78-5502-9c7d-44cdd304349d','e1000001-0000-4000-8000-000000000004','step',3,'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9d846536-1df2-5a12-99ad-f43f7dcfe624','e1000001-0000-4000-8000-000000000004','step',4,'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2dbe1b74-a909-58c3-9029-2ae4ef8a7a94','e1000001-0000-4000-8000-000000000004','step',5,'Perform the amount of repetitions prescribed in the program.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6505db1f-d8f0-568c-9493-f8f272a3db98','e1000001-0000-4000-8000-000000000004','cue',1,'Bar over mid-foot, shins close','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b53aee4b-a146-503a-96a5-6a6070eedbdc','e1000001-0000-4000-8000-000000000004','cue',2,'Pull the slack out of the bar before lifting','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('28050992-10cd-52d2-b682-5373a70521a2','e1000001-0000-4000-8000-000000000004','cue',3,'Push the floor away, then drive hips through','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('11cd0acb-4f5f-5999-a565-c49b229d311c','e1000001-0000-4000-8000-000000000004','mistake',1,'Rounding the back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35b492a4-bf22-596f-aef3-fa3302b01bf0','e1000001-0000-4000-8000-000000000004','mistake',2,'Bar drifting away from legs','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ab2134d5-d6b9-5af4-9855-3e9ac936eb21','e1000001-0000-4000-8000-000000000004','mistake',3,'Jerking the bar off the floor','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('020897ef-7492-550c-8f27-3e12e3fb7813','e1000001-0000-4000-8000-00000000001a','step',1,'Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b17f5cf9-8571-5487-99ef-d635bbeb7447','e1000001-0000-4000-8000-00000000001a','step',2,'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5ac11796-14d6-5204-9f1b-cf3a857ef47c','e1000001-0000-4000-8000-00000000001a','step',3,'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('28c5d1b7-cc08-5b09-b0f1-c0ce9bac6dc4','e1000001-0000-4000-8000-00000000001a','cue',1,'Upper back on bench edge, bar padded over hips','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a2d427e8-b152-5a2d-9cc1-3a45af0e7771','e1000001-0000-4000-8000-00000000001a','cue',2,'Tuck chin and ribs down','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f55ef57e-ff7f-5077-a0e6-affa7e9c1e60','e1000001-0000-4000-8000-00000000001a','cue',3,'Squeeze glutes hard at the top','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4d2e080c-0cf3-5369-9101-286a8f002068','e1000001-0000-4000-8000-00000000001a','mistake',1,'Arching the lower back at the top','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59c650b5-22b9-57ca-8a55-e5126889bf93','e1000001-0000-4000-8000-00000000001a','mistake',2,'Feet too far/close','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('43b8e303-1001-5ec6-a809-0bbeec7d8cd6','e1000001-0000-4000-8000-00000000001a','mistake',3,'Pushing through toes','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cb753d2d-da1a-5100-97d2-e29406ff3827','e1000001-0000-4000-8000-000000000001','step',1,'To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f31db872-acbe-5030-9341-455cb05d7ba4','e1000001-0000-4000-8000-000000000001','step',2,'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('455a1fab-9070-5aaf-920f-4d26bf91d20f','e1000001-0000-4000-8000-000000000001','step',3,'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('52097e66-34b3-56ca-8d36-c04ebeba72ce','e1000001-0000-4000-8000-000000000001','step',4,'Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dba5bf04-e135-5691-80c8-cac2a825783c','e1000001-0000-4000-8000-000000000001','step',5,'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2e0901ef-7a57-525d-bc5a-3288b403a2c9','e1000001-0000-4000-8000-000000000001','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea3c0c56-5bdc-588c-9ade-f0df149a52d0','e1000001-0000-4000-8000-000000000001','cue',1,'Bar on upper traps, hands just outside shoulders','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07eae4cf-fc89-52b1-9a71-b55fe52d5fe4','e1000001-0000-4000-8000-000000000001','cue',2,'Break at hips and knees together','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37bfe616-ddd0-5ed2-a1a8-859219ee8af0','e1000001-0000-4000-8000-000000000001','cue',3,'Squat to at least parallel if mobility allows','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1b2d1d43-cc0b-5b8f-91f9-63e0c29e3d12','e1000001-0000-4000-8000-000000000001','mistake',1,'Good-morning squat (hips rise first)','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9bffff3c-e3dc-5760-b1be-9e84a0a13ccc','e1000001-0000-4000-8000-000000000001','mistake',2,'Knees caving','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be0b9b59-9095-53d5-8326-777975f040ac','e1000001-0000-4000-8000-000000000001','mistake',3,'Losing brace at the bottom','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4a9cd801-bba9-5627-b41a-bdc393388d9b','e1000001-0000-4000-8000-00000000000e','step',1,'Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5d6c6802-eebf-559a-b66b-d342741ea704','e1000001-0000-4000-8000-00000000000e','step',2,'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0e36f917-73c4-5cb3-8faf-229f69880a76','e1000001-0000-4000-8000-00000000000e','step',3,'Then inhale and slowly lower the barbell back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a3c3fa77-cef9-5593-bbb7-06c0156b9957','e1000001-0000-4000-8000-00000000000e','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('68dc83d4-921a-54ed-904e-32503b694dff','e1000001-0000-4000-8000-00000000000e','cue',1,'Hinge to ~45 degrees, neutral back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('26ccce5b-717c-524e-a879-4152d71b6b86','e1000001-0000-4000-8000-00000000000e','cue',2,'Pull to lower ribs','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('288c634a-9923-59ec-98b5-468da6b90876','e1000001-0000-4000-8000-00000000000e','cue',3,'Pause briefly at the top','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('70f9041c-d15b-52f5-a70f-8ac953ad39fa','e1000001-0000-4000-8000-00000000000e','mistake',1,'Standing up during the row','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('41198434-5832-5159-a7d7-957cabb718e0','e1000001-0000-4000-8000-00000000000e','mistake',2,'Rounding the back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a8cc5365-78f9-552b-86fc-dcbf5e46e23b','e1000001-0000-4000-8000-00000000000e','mistake',3,'Using momentum','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('108202a8-bb84-50c0-aef3-794128ae057c','e1000001-0000-4000-8000-00000000001d','step',1,'Start on your hands and knees with your hands under your shoulders and knees under your hips.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6eacbbda-ecff-5e46-ac7e-6ef607e40d0d','e1000001-0000-4000-8000-00000000001d','step',2,'Brace your core to keep your back flat.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dce86a2a-cae0-5193-a8d4-9cac3ed8b8cd','e1000001-0000-4000-8000-00000000001d','step',3,'Reach one arm forward and the opposite leg back until both are straight.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a4dc6e0-10a4-5728-ae6d-09a3c989ca42','e1000001-0000-4000-8000-00000000001d','step',4,'Hold for a second, return, and switch sides.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('71fff1be-f9ac-5bc7-ae84-f4a380c08da7','e1000001-0000-4000-8000-00000000001d','cue',1,'Keep hips level','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1118e507-8197-5a9b-baf3-58b339c0b602','e1000001-0000-4000-8000-00000000001d','cue',2,'Reach long rather than high','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e20a63dd-4212-5ffa-869e-84cba19740dc','e1000001-0000-4000-8000-00000000001d','cue',3,'Move slowly','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f24a4f9b-cc98-5dcd-8985-8121c1d8c7f7','e1000001-0000-4000-8000-00000000001d','mistake',1,'Arching the lower back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1227c63d-0a3b-5ad6-b4d3-7960e10739ba','e1000001-0000-4000-8000-00000000001d','mistake',2,'Rotating the hips','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0cd6b1cb-838f-5f95-9aa4-a932d3acfa4b','e1000001-0000-4000-8000-00000000001d','mistake',3,'Rushing the reps','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e013f05e-f943-5de6-b4c1-e8c3b35d71a9','e1000001-0000-4000-8000-000000000014','step',1,'Stand tall with your feet hip-width apart.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9202a7ac-109e-5cb6-bcf5-94b2187e1efb','e1000001-0000-4000-8000-000000000014','step',2,'Step forward into a long stride and lower your back knee toward the floor.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c4059f56-5441-541c-b121-4c943915d506','e1000001-0000-4000-8000-000000000014','step',3,'Keep your front shin close to vertical as both knees bend to about 90 degrees.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2ad17e40-5129-5068-ac28-79231fdb9b4f','e1000001-0000-4000-8000-000000000014','step',4,'Push through your front foot and step through into the next stride, alternating legs.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aaac7698-c8c2-5a2c-8b10-33163f80085a','e1000001-0000-4000-8000-000000000014','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
