INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f52adc60-dbb3-5953-93ee-6c285bd11fde','e1000001-0000-4000-8000-000000000014','mistake',1,'Front knee collapsing inward','en','ai_authored:pattern');
