INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c9bb238-6887-5592-9d58-d861d9295c01','e1000001-0000-4000-8000-000000000022','step',1,'To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc653fbe-09b2-5a21-891c-91ac2cde017a','e1000001-0000-4000-8000-000000000022','step',2,'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8af5d927-33ad-5906-abaf-ef4177e4c251','e1000001-0000-4000-8000-000000000022','step',3,'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('835ed159-51c8-55d1-8775-391ae2ff1d79','e1000001-0000-4000-8000-000000000022','step',4,'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('84966a51-478f-5db2-b33c-b5851ca2106f','e1000001-0000-4000-8000-000000000022','step',5,'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
