INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('425f9f97-166a-5e3d-832f-89cf981b8d8c','e1000001-0000-4000-8000-00000000001c','step',2,'Bring your feet, knees, and hips up to 90 degrees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6252ebd3-9d90-5ab9-b84e-3e89a95d33e7','e1000001-0000-4000-8000-00000000001c','step',3,'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position. Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c762d419-84ac-5a0c-aeee-121cab1c5a54','e1000001-0000-4000-8000-00000000001c','step',4,'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cfd06acb-d4b3-5915-8fab-045a87417fae','e1000001-0000-4000-8000-00000000001c','step',5,'Stay tight and return the working leg to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fae5da95-bcd5-5e4f-b899-ba5a83ea0763','e1000001-0000-4000-8000-00000000001c','step',6,'Repeat on the opposite side, alternating until the set is complete.','en','source:free_exercise_db');
