INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fcc22a68-8d78-581e-bccf-fa6b04e632a3','e1000001-0000-4000-8000-00000000001e','step',1,'Start with 3-5 minutes of easy walking to warm up.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59fca931-49a1-5190-8491-97f21969ea12','e1000001-0000-4000-8000-00000000001e','step',2,'Build up to a brisk walking pace.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d5fe8ff-4c32-54a0-8d5d-75d3a86b75bb','e1000001-0000-4000-8000-00000000001e','step',3,'Stand tall with relaxed shoulders and let your arms swing naturally.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1de247dc-3af3-53bb-913a-8c8f52724b0e','e1000001-0000-4000-8000-00000000001e','step',4,'Ease down to a walk for a few minutes to cool down.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('69ef9392-f548-57c2-aec4-70b0fc6ae54e','e1000001-0000-4000-8000-00000000001e','cue',1,'Grip handles in the centre','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e34c2be6-8705-5d5c-be1c-88a3b1458c2a','e1000001-0000-4000-8000-00000000001e','cue',2,'Stand tall, shoulders down','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('02de4842-6e65-5953-b174-4378a2ef4eca','e1000001-0000-4000-8000-00000000001e','cue',3,'Walk with short steps','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f0182dfa-f51c-5972-b84d-d027e584752c','e1000001-0000-4000-8000-00000000001e','mistake',1,'Leaning','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c34a16be-7559-51f7-b8e5-a3ae64cd217b','e1000001-0000-4000-8000-00000000001e','mistake',2,'Shrugging','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eb3544b2-007f-53f6-a342-5afb7e2e89e7','e1000001-0000-4000-8000-00000000001e','mistake',3,'Letting weights swing','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d7f52a0a-c3b6-5f94-89e6-932b70e50462','e1000001-0000-4000-8000-000000000002','step',1,'To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f436e815-73f6-5e68-b011-da3089560421','e1000001-0000-4000-8000-000000000002','step',2,'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('515b5312-e0a6-55ac-bfb9-da474471c107','e1000001-0000-4000-8000-000000000002','step',3,'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('558ef22b-4bf9-5018-b6c2-3b380bfeafe1','e1000001-0000-4000-8000-000000000002','step',4,'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dd1b6a1f-db82-5090-9819-8d347f0692ab','e1000001-0000-4000-8000-000000000002','step',5,'Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6ec04003-7aa5-5021-aecf-bd449e6b1038','e1000001-0000-4000-8000-000000000002','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d91c2ffc-181f-58c7-a6fa-4f46b459c980','e1000001-0000-4000-8000-000000000002','cue',1,'Brace your core before you descend','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c9df31f8-0466-5fa3-8cdf-2288677f3962','e1000001-0000-4000-8000-000000000002','cue',2,'Knees track over your toes','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a86d62b0-54ca-5d77-a4fb-35fb57696387','e1000001-0000-4000-8000-000000000002','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3d68c825-53b3-56b3-b856-09960aa19198','e1000001-0000-4000-8000-000000000002','mistake',1,'Knees caving inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2f1d4329-1d49-5e41-9668-7be66aee2682','e1000001-0000-4000-8000-000000000002','mistake',2,'Heels lifting off the floor','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('15029831-2212-5c84-bb7b-7a97630d655b','e1000001-0000-4000-8000-000000000002','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3c1f9bdd-7092-5749-9aca-054b04161cdd','e1000001-0000-4000-8000-000000000020','step',1,'Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('17d15314-c478-5d22-855c-a8d1576f1186','e1000001-0000-4000-8000-000000000020','step',2,'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ff874b5f-8898-51b2-b98d-487c2f1aa540','e1000001-0000-4000-8000-000000000020','step',3,'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('664e0f2b-64f2-5b91-b952-dbf427fae64d','e1000001-0000-4000-8000-000000000020','cue',1,'Hold the weight at your chest, elbows down','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4d784b58-1698-50a8-9992-10c37826a135','e1000001-0000-4000-8000-000000000020','cue',2,'Sit between your heels','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('464b5aaa-5b46-56c1-9d06-aba5db72c52b','e1000001-0000-4000-8000-000000000020','cue',3,'Keep chest up','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c57d9871-4130-5ed4-8358-79d34dc51363','e1000001-0000-4000-8000-000000000020','mistake',1,'Rounding forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3468ae92-73ea-5b70-9f14-c3348d183ac5','e1000001-0000-4000-8000-000000000020','mistake',2,'Heels lifting','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('518eed48-a0e7-5e3c-9986-5f8796af10b0','e1000001-0000-4000-8000-000000000020','mistake',3,'Knees caving','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('196eba21-bf10-5210-99ba-c92866b279e4','e1000001-0000-4000-8000-000000000006','step',1,'Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('48067b9e-7a5b-57a5-93e7-136f08942355','e1000001-0000-4000-8000-000000000006','step',2,'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('957ba0d8-8f47-500a-9f59-d1b0994b33c9','e1000001-0000-4000-8000-000000000006','step',3,'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1784ea19-4745-5fc6-b46e-9db606e75845','e1000001-0000-4000-8000-000000000006','step',4,'Lock your arms at the top, hold for a second, and then start slowly lowering the weight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e9c1e04e-3c11-5989-b2d9-78b70fc656e2','e1000001-0000-4000-8000-000000000006','step',5,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d425fb36-f7cc-5ea5-9cc9-6cf8c1e5174b','e1000001-0000-4000-8000-000000000006','step',6,'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6511ea62-eff8-5db3-a266-7fbbcbc6fc07','e1000001-0000-4000-8000-000000000006','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9cd492d7-ac21-5506-b877-a7dd11189d01','e1000001-0000-4000-8000-000000000006','cue',2,'Wrists stacked over elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ecb32be3-c029-5bb0-89a2-3e3cf8a40428','e1000001-0000-4000-8000-000000000006','cue',3,'Lower under control to chest level','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('055f50f3-bd96-59b9-b748-bc42cd3f85bb','e1000001-0000-4000-8000-000000000006','mistake',1,'Flaring elbows to 90 degrees','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c8ed20c7-89e0-521a-97c1-4e5e75fc742f','e1000001-0000-4000-8000-000000000006','mistake',2,'Bouncing off the chest','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c3a9d20e-3f1f-5489-b104-817166eba4b4','e1000001-0000-4000-8000-000000000006','mistake',3,'Lifting hips off the bench','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62cdd559-f552-53da-8a5b-1c53baeae7c9','e1000001-0000-4000-8000-000000000018','step',1,'First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ec6ef6d5-0a73-53ef-9ed8-5e1d1c3a051f','e1000001-0000-4000-8000-000000000018','step',2,'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ef8b33a1-194e-5781-a6e7-5755eb869cc4','e1000001-0000-4000-8000-000000000018','step',3,'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('49b95b63-2dc2-5e0d-8f93-9ed3acc64df3','e1000001-0000-4000-8000-000000000018','step',4,'Repeat for the recommended amount of times.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5d7abcb2-48cd-5ca8-8129-02545ff3240e','e1000001-0000-4000-8000-000000000018','cue',1,'Pause briefly at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e7184f39-6878-51a9-9168-4a31096bb0de','e1000001-0000-4000-8000-000000000018','cue',2,'Control the lowering phase','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('54bc08f0-59da-520d-8b28-53ebc84bd9aa','e1000001-0000-4000-8000-000000000018','cue',3,'Keep hips pressed into the seat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c553598-252b-574e-84ab-5250f3b9110b','e1000001-0000-4000-8000-000000000018','mistake',1,'Swinging the weight up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('65d6e737-b9d3-54af-a25e-12755ce83a7b','e1000001-0000-4000-8000-000000000018','mistake',2,'Locking the knees hard','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d2b9b836-e9d0-57d3-ba56-7aa28d764cf2','e1000001-0000-4000-8000-000000000018','mistake',3,'Lifting hips off the pad','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a07c542e-2fe1-5fb9-9f83-febf18d7eecf','e1000001-0000-4000-8000-000000000016','step',1,'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dfadfe4f-8f31-5c90-86b3-a408bee210b6','e1000001-0000-4000-8000-000000000016','step',2,'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3290e30a-e6f1-5634-be41-f23338e5d6c2','e1000001-0000-4000-8000-000000000016','step',3,'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('95b558d0-6480-5ee5-b625-657064fe8065','e1000001-0000-4000-8000-000000000016','step',4,'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b9d197d1-427d-5363-ae93-e4ab4e14b3fd','e1000001-0000-4000-8000-000000000016','cue',1,'Feet shoulder-width mid-platform','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('feb5b33b-2e5d-56f3-8016-4783e1f364ea','e1000001-0000-4000-8000-000000000016','cue',2,'Lower until knees ~90 degrees','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b40b8f22-3fe6-5ed2-96aa-5bb978b28336','e1000001-0000-4000-8000-000000000016','cue',3,'Keep lower back on the pad','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6c6af9e0-8a0c-55e4-87e0-5cb19ee2cb28','e1000001-0000-4000-8000-000000000016','mistake',1,'Locking knees','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dba90f26-cf9b-54e6-9281-18b4a9e0af03','e1000001-0000-4000-8000-000000000016','mistake',2,'Hips rolling off the pad','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('43dfd235-e0b0-5497-b57f-376b53414101','e1000001-0000-4000-8000-000000000016','mistake',3,'Knees caving','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7930c8a3-0282-558f-9718-12571bdd741b','e1000001-0000-4000-8000-000000000017','step',1,'Lie face down on the leg curl machine with the pad just above your heels.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0ff5d104-47d3-57f8-8106-90343c15421d','e1000001-0000-4000-8000-000000000017','step',2,'Hold the handles and keep your hips still.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a3b7630c-925d-565b-bfea-7ad2fafd7bae','e1000001-0000-4000-8000-000000000017','step',3,'Curl your heels toward your glutes as far as you can.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f807885f-03e8-5111-a91f-8f42ef1004f3','e1000001-0000-4000-8000-000000000017','step',4,'Lower slowly until your knees are almost straight.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('78409844-ca0d-54a1-8903-50f6fb7923ad','e1000001-0000-4000-8000-000000000017','cue',1,'Keep hips pressed down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0d97e22e-fcc1-5cbc-b1e6-51d9420a6527','e1000001-0000-4000-8000-000000000017','cue',2,'Curl through the full range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c8cf34a-1dbb-5aa4-ad46-dc8e833dc1dd','e1000001-0000-4000-8000-000000000017','cue',3,'Lower slowly','en','ai_authored:pattern');
