INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e87c7517-5b3d-512f-beb8-88edb666f0f5','e1000001-0000-4000-8000-000000000017','mistake',2,'Using momentum','en','ai_authored:pattern');
