INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8216efd4-706f-56d0-aadf-95c149610239','e1000001-0000-4000-8000-00000000001b','step',1,'Place your forearms on the floor with your elbows under your shoulders.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37e6646b-9b6c-56e3-be6c-1a9653d03193','e1000001-0000-4000-8000-00000000001b','step',2,'Step your feet back so your body is straight from head to heels.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('21cbb123-e7cf-5034-8f7b-e107e4a5c00d','e1000001-0000-4000-8000-00000000001b','step',3,'Brace your core and squeeze your glutes.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fc9f446c-37a7-5699-8e67-087bfae8feab','e1000001-0000-4000-8000-00000000001b','step',4,'Hold the position, breathing steadily, without letting your hips sag.','en','ai_authored:fitbud_curated');
