INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('74eb70a7-bf6b-5faa-b293-119f659cb63c','e1000001-0000-4000-8000-00000000001b','mistake',2,'Hips too high','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5a6e4de9-7841-5506-879d-ed3a1ea45c54','e1000001-0000-4000-8000-00000000001b','mistake',3,'Looking up','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fabfea19-5557-58ca-b2e9-db4a77c9aa8d','e1000001-0000-4000-8000-00000000000b','step',1,'Grab the pull-up bar with the palms facing forward using the prescribed grip. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('24b62a86-96e8-5796-bec7-61913fb7bd72','e1000001-0000-4000-8000-00000000000b','step',2,'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('08d1c1c8-4570-5d42-941b-b3c98769f61e','e1000001-0000-4000-8000-00000000000b','step',3,'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a0a7ba31-4537-530a-9033-27d8f54248cd','e1000001-0000-4000-8000-00000000000b','step',4,'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('12e7dd1e-29ec-5f69-a4ae-df0877f79b86','e1000001-0000-4000-8000-00000000000b','step',5,'Repeat this motion for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('874c6a2a-f6af-5f05-896f-a609a154def2','e1000001-0000-4000-8000-00000000000b','cue',1,'Start from a dead hang','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('da14ca16-ae38-5ba2-a69a-05b574a56a7e','e1000001-0000-4000-8000-00000000000b','cue',2,'Pull chest toward the bar','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('22e0e053-9228-5c25-bdaf-1dd171d93639','e1000001-0000-4000-8000-00000000000b','cue',3,'Lower to full hang every rep','en','ai_authored:specific');
