INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('13840ce1-a4e9-5f82-9a38-d6c895be6dc8','e1000001-0000-4000-8000-00000000000b','mistake',3,'Half reps','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ca66d2d5-e9a1-5073-82cb-c3f8c9b78a1d','e1000001-0000-4000-8000-000000000007','step',1,'Lie on the floor face down and place your hands slightly wider than shoulder-width apart while holding your torso up at arms length.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1082029e-d222-52b4-9a42-8110d5cb9b99','e1000001-0000-4000-8000-000000000007','step',2,'Next, lower yourself downward until your chest almost touches the floor as you inhale.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cfbd64a7-818d-5f34-ae9f-37f30a818505','e1000001-0000-4000-8000-000000000007','step',3,'Now breathe out and press your upper body back up to the starting position while squeezing your chest.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('04cfc81b-e86c-524f-9019-eba1c5cfbe57','e1000001-0000-4000-8000-000000000007','step',4,'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('131cbc12-89d9-5a5b-b720-458759d8a6b5','e1000001-0000-4000-8000-000000000007','cue',1,'Hands just outside shoulders','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('708a338c-f15e-5089-830e-6f2c034751e2','e1000001-0000-4000-8000-000000000007','cue',2,'Body in one straight line','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('39d8fd63-c233-5e43-9185-d43adf77c7c5','e1000001-0000-4000-8000-000000000007','cue',3,'Chest to fist-height from the floor','en','ai_authored:specific');
