INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fb7abeb0-9f95-5a65-8a9c-fc818d407600','e1000001-0000-4000-8000-000000000003','step',1,'Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a8c0bd3-7d67-5534-930a-38fb500d897f','e1000001-0000-4000-8000-000000000003','step',2,'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('991eed28-4a3f-5c14-8b91-8f83a9f3c26c','e1000001-0000-4000-8000-000000000003','step',3,'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('39e2b05d-bc47-5ae8-be57-408aafc08b0d','e1000001-0000-4000-8000-000000000003','step',4,'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Hold your breath as you lower and exhale as you complete the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35346a8f-c86c-5c84-8744-30a80173754b','e1000001-0000-4000-8000-000000000003','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
