INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('41034d81-bfba-5170-8f40-abc18f8adab7','e1000001-0000-4000-8000-000000000003','cue',3,'Stop when hamstrings are fully stretched','en','ai_authored:specific');
