INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('857fbf9e-55d8-50fc-b818-3e5ade6a7d2d','e1000001-0000-4000-8000-000000000003','mistake',3,'Letting the bar drift forward','en','ai_authored:specific');
