INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62a39a51-f894-59b5-82b1-05220033689e','e1000001-0000-4000-8000-00000000000d','step',3,'Pull the cable handles to your lower ribs, driving your elbows back.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ff5ae6e-c871-58eb-a097-e9f3f5a56d92','e1000001-0000-4000-8000-00000000000d','step',4,'Pause, then let your arms straighten slowly without rounding forward.','en','ai_authored:fitbud_curated');
