INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6e688d8e-c453-5b4e-8636-2f93ed865582','e1000001-0000-4000-8000-00000000000a','mistake',3,'Raising above shoulder height with heavy weight','en','ai_authored:specific');
