INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1657fccd-5fe4-59da-bebe-b1c2ca03180a','e1000001-0000-4000-8000-00000000001f','step',1,'Stand with your feet a little wider than your hips and the kettlebell a foot in front of you.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ccee1a73-f274-5a2a-9136-05343cb4fa03','e1000001-0000-4000-8000-00000000001f','step',2,'Hinge and grip the handle with one hand, then hike it back between your legs.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0daeb364-a46f-5751-a144-118be6da7306','e1000001-0000-4000-8000-00000000001f','step',3,'Snap your hips forward to swing the kettlebell to chest height with a straight arm.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fe76b13f-6ee7-5090-b8cc-bf57a330ef7d','e1000001-0000-4000-8000-00000000001f','step',4,'Let it swing back between your legs as you hinge and go straight into the next rep.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('76bdd44a-cd72-5d55-9907-5242d6d504a7','e1000001-0000-4000-8000-00000000001f','step',5,'Finish all reps on one side, then switch sides and repeat.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('34ba5dbb-3469-5f63-9a4d-5c8440c4c8b9','e1000001-0000-4000-8000-00000000001f','cue',1,'Hike the bell back between the legs','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d537a793-bfe0-58ef-b46b-da105b7ee377','e1000001-0000-4000-8000-00000000001f','cue',2,'Snap hips forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a61cf8ae-e59c-5986-86b1-c12c82749d28','e1000001-0000-4000-8000-00000000001f','cue',3,'Let the bell float to chest height','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7a1bc774-e894-51bc-921e-1bb007c6d416','e1000001-0000-4000-8000-00000000001f','mistake',1,'Squatting the swing','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bf0cbb22-c37b-50ba-a525-8cff5c6f1a15','e1000001-0000-4000-8000-00000000001f','mistake',2,'Lifting with the arm','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c36c9da-5452-5447-b6b3-65fe9c9fa5c4','e1000001-0000-4000-8000-00000000001f','mistake',3,'Hyperextending at the top','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('68e2c7fd-df81-56f8-a9da-101380b75dbc','e1000001-0000-4000-8000-000000000015','step',1,'Position yourself into a staggered stance with the rear foot elevated and front foot forward.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac79588c-03e8-5c4b-a79c-386de559f9e9','e1000001-0000-4000-8000-000000000015','step',2,'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('92635b0a-6a7b-596a-894a-f389f2b4517e','e1000001-0000-4000-8000-000000000015','step',3,'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('133e585f-fa09-56d6-b657-047d37ec9fa6','e1000001-0000-4000-8000-000000000015','step',4,'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('74b716cc-0f58-552b-b387-3eede702bab3','e1000001-0000-4000-8000-000000000015','step',5,'Finish all reps on one side, then switch sides and repeat.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dc98b95c-531c-5620-8037-5d99471ca2be','e1000001-0000-4000-8000-000000000015','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac4ca29e-c8ab-5a56-9ac2-5fcb73e1e768','e1000001-0000-4000-8000-000000000015','cue',2,'Lower the back knee straight down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d26aab18-7cb7-5ef7-8537-ca4968a6955d','e1000001-0000-4000-8000-000000000015','cue',3,'Keep your torso tall','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59dd1c41-fff1-53c2-980f-dc6e358f89c6','e1000001-0000-4000-8000-000000000015','mistake',1,'Front knee collapsing inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('125b8aba-9e7d-585b-924d-17902552259f','e1000001-0000-4000-8000-000000000015','mistake',2,'Pushing off the back foot instead of the front heel','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('81fc0b15-0152-5623-bdeb-65078440864a','e1000001-0000-4000-8000-000000000015','mistake',3,'Short, choppy steps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('36b58e6e-0685-5e54-81f0-a1e7b6af1890','e1000001-0000-4000-8000-000000000019','step',1,'Adjust the padded lever of the calf raise machine to fit your height.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e45e9e6b-a7ad-54c1-a002-05a552a803b6','e1000001-0000-4000-8000-000000000019','step',2,'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('065dfcd3-2e9d-5056-a529-96db90b75247','e1000001-0000-4000-8000-000000000019','step',3,'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ff807616-5446-56d2-a44b-3cc76e97b0c2','e1000001-0000-4000-8000-000000000019','step',4,'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3642328f-1b27-5d7a-a5d9-d2d854e2e05c','e1000001-0000-4000-8000-000000000019','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('024d7919-a2f6-51f4-abd5-bb6bb0c1a8d3','e1000001-0000-4000-8000-000000000019','cue',1,'Rise as high as possible onto the balls of the feet','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2d91adc7-0f68-540f-bd25-d79967c4d674','e1000001-0000-4000-8000-000000000019','cue',2,'Pause at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8edd8490-7c49-55cd-8cf2-86fefd16d54e','e1000001-0000-4000-8000-000000000019','cue',3,'Lower fully into a stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eeb0315c-0336-5561-a565-9f2ecfac0567','e1000001-0000-4000-8000-000000000019','mistake',1,'Bouncing at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('16a92e4d-bc21-5f04-944d-2597552058c8','e1000001-0000-4000-8000-000000000019','mistake',2,'Bending the knees to cheat','en','ai_authored:pattern');
