INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('340f8008-7ca5-5f17-a673-45f4fbdc26c3','e1000001-0000-4000-8000-000000000008','step',1,'Stand tall with your feet about hip-width apart.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('54cb15c0-0dd5-57da-93c3-03ab0e14a6f8','e1000001-0000-4000-8000-000000000008','step',2,'Hold the barbell at shoulder height.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4ff06f0-5046-5fdc-ab52-d3403862a520','e1000001-0000-4000-8000-000000000008','step',3,'Brace your core and press the barbell straight overhead until your arms are straight.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('200f9869-3a17-5970-a4db-eaf3c8e757b1','e1000001-0000-4000-8000-000000000008','step',4,'Lower the barbell under control back to shoulder height.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('acff58fd-806c-5c16-8212-39cd57b9bd80','e1000001-0000-4000-8000-000000000008','cue',1,'Bar starts on front shoulders','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4fa51ac-7636-5f89-a9fc-d188d3b5689f','e1000001-0000-4000-8000-000000000008','cue',2,'Head moves back then through','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('034276f8-8bc3-59d2-9254-e24864246304','e1000001-0000-4000-8000-000000000008','cue',3,'Lock out overhead with biceps by ears','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac4c2915-fbe2-5939-80cc-4316520ae364','e1000001-0000-4000-8000-000000000008','mistake',1,'Leaning back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8474133c-9d01-5a26-acb0-472da589f481','e1000001-0000-4000-8000-000000000008','mistake',2,'Pressing forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dad81cfb-fed4-506d-bcc8-5d9c1a111979','e1000001-0000-4000-8000-000000000008','mistake',3,'Not locking out','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('69ea7134-b542-5cb2-b6b8-9cac6548464b','e1000001-0000-4000-8000-000000000024','step',1,'Set up on the bike and adjust it to fit you.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('162fe74e-eca9-5721-91be-44bd1d67b973','e1000001-0000-4000-8000-000000000024','step',2,'Warm up for 3-5 minutes at an easy effort.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('51bd4d47-ae1c-5fe5-8c94-15f54f061602','e1000001-0000-4000-8000-000000000024','step',3,'Build to your target effort and hold a steady rhythm.','en','ai_authored:fitbud_curated');
