INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('160935b9-b781-52a0-ab84-bd701886e7da','e1000001-0000-4000-8000-000000000023','mistake',3,'Looking down','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('840129e8-9925-5f48-9139-b97634126035','e1000001-0000-4000-8000-000000000012','step',1,'Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1b8f89af-780b-5a0f-adcd-912dfed18acd','e1000001-0000-4000-8000-000000000012','step',2,'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('917c7c39-7527-512a-b055-3279fc0e0917','e1000001-0000-4000-8000-000000000012','step',3,'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3329fbd6-0ce3-57bd-95b4-7053bcbbb437','e1000001-0000-4000-8000-000000000012','step',4,'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('14a9937b-ff7e-5865-b336-56eec15d3a20','e1000001-0000-4000-8000-000000000012','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d41c8186-9c6b-5588-bdbf-dbd445bd8df4','e1000001-0000-4000-8000-000000000012','cue',1,'Elbows pinned to sides','en','ai_authored:specific');
