INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c796669-0b62-5ca3-ae95-3c57b1682021','bfd9d15c-803e-56e4-a858-c80a65b7ec6a','step',2,'Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('536007dc-56e3-581c-9e3d-daae9e7d8e83','bfd9d15c-803e-56e4-a858-c80a65b7ec6a','step',3,'Slowly roll the ab roller straight forward, stretching your body into a straight position. Breathe in during this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('18db13c9-e886-5e79-9c39-203e013144d2','bfd9d15c-803e-56e4-a858-c80a65b7ec6a','step',4,'After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out.','en','source:free_exercise_db');
