INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a16e3609-f8e8-5b62-9e2a-b23d79c66ba7','95171473-ba6a-5e73-ac0d-af775493eac5','step',2,'Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5e1a076c-71ed-5d1c-851f-3bb0160554d0','95171473-ba6a-5e73-ac0d-af775493eac5','step',3,'Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dd260f9d-c91d-564e-9579-e9f13196c66d','95171473-ba6a-5e73-ac0d-af775493eac5','step',4,'Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.','en','source:free_exercise_db');
