INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5b8411c5-fa96-5a18-8acc-250722c44691','595d506b-800b-55eb-8922-4e65cc3b14a9','step',1,'Lie flat on the floor with your lower back pressed to the ground. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('67191523-79fe-5cee-9ff0-7cdd31202108','595d506b-800b-55eb-8922-4e65cc3b14a9','step',2,'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('535eff70-a9ec-5b22-b790-71ceed3472e8','595d506b-800b-55eb-8922-4e65cc3b14a9','step',3,'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('60783d10-8565-5066-85c8-878b2927bd0f','595d506b-800b-55eb-8922-4e65cc3b14a9','step',4,'Go back to the initial position as you breathe in.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('64754625-014e-5a2f-8be8-185d6de6198f','595d506b-800b-55eb-8922-4e65cc3b14a9','step',5,'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7b60dee4-f7ad-55e5-a744-479d238d9d67','595d506b-800b-55eb-8922-4e65cc3b14a9','step',6,'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.','en','source:free_exercise_db+fitbud_curated_edit');
