INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be500799-e45f-5d62-89f6-a1bc5b78a519','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',1,'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b28ea8f3-61ce-50e9-90b3-463654cabeb2','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',2,'The palms of the hands should be facing your torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7b51226-d6cf-52ea-a3f7-f1139f7313f0','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',3,'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6e05a1ac-d2cc-58d1-bd63-cefc2a1d856c','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',4,'Slowly begin to bring the dumbbells back to starting position as your breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1e7ae0df-dc18-5a91-add4-33896937323c','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',5,'Repeat the movement with the left hand. This equals one repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('86610d6f-8bb6-51d1-8157-de425b44b1ec','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',6,'Continue alternating in this manner for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07f511ef-fd4b-5aa3-91a5-2c83943df67f','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','cue',1,'Keep elbows pinned at your sides','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d5c4bd4f-3fa6-5f86-b474-91fd93506047','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','cue',2,'Squeeze at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d34557e0-0c45-556d-9783-a4344153011e','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','cue',3,'Lower all the way under control','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('17952e53-9293-5635-846a-c70013b62f0e','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','mistake',1,'Swinging the body','en','ai_authored:pattern');
