INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2300b77-79bd-571b-a41b-67161434bcd3','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','mistake',3,'Cutting the range short','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d8d78d8-9ed4-582c-86c3-9d755045bd98','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',1,'Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7ce8847-cc96-5b31-a261-dbce06608d69','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',2,'Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7073aab4-cbe1-59ce-8b31-cc17cb99b3f0','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',3,'Now go back slowly to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('26f398b5-490d-56a9-bb97-7944a2059f0e','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',4,'Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5b68b28f-19d8-5f5f-81e6-f0faedb628c2','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',5,'Continue alternating sides in this manner until all prescribed repetitions are done.','en','source:free_exercise_db');
