INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('01d203d6-13ae-58ab-872e-ced324a83ad8','628f1ac9-0ebf-5a43-b784-145326bc7ef1','cue',2,'Move with control','en','ai_authored:pattern');
