INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8576fa40-76f1-5354-82a3-4717cc28616e','026da59b-63e6-561f-bb1b-38da5804ba42','step',2,'Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aaad4cdc-f349-5399-bf14-f9219cea2e9b','026da59b-63e6-561f-bb1b-38da5804ba42','step',3,'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('06a5a14f-34fa-54ec-a552-fa0ee06432b9','026da59b-63e6-561f-bb1b-38da5804ba42','step',4,'After a brief pause, return to the starting position.','en','source:free_exercise_db');
