INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('11e67d7d-e83e-5d0c-85a7-af4819679a8b','20ef3756-a490-523e-b237-eafabad468fd','step',3,'Extend and lift the arms straight in front of you. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b0cda2f4-54ae-5bf7-936a-95b96489703c','20ef3756-a490-523e-b237-eafabad468fd','step',4,'As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.','en','source:free_exercise_db');
