INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9def124b-daf6-5538-bcfe-4fffe84e89c2','3c9e5cfd-7f8e-56ed-8711-2bfa8a1ca6a3','step',2,'While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ae6bded8-d822-5bf7-b545-7a1b5eab8cef','3c9e5cfd-7f8e-56ed-8711-2bfa8a1ca6a3','step',3,'Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.','en','source:free_exercise_db');
