INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e13fc2b3-d055-58ac-aae0-19c8ba636625','402ba377-2155-51ea-a420-1ad8455cb448','step',3,'Stand up straight and hold onto the post if needed. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('74e19747-6d8c-593c-b8f2-bd4f039244aa','402ba377-2155-51ea-a420-1ad8455cb448','step',4,'Keeping the knee straight, raise your right legs out to the side as far as you can.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b9b70086-40e7-5efe-be84-72849e8ec314','402ba377-2155-51ea-a420-1ad8455cb448','step',5,'Return to the starting position and repeat for the desired rep count.','en','source:free_exercise_db');
