INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ffbae70c-09d7-5bc2-9804-f4f95b6f00dc','b4ea0597-1b8b-56e8-aa6c-7da261fcf0b4','step',1,'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1eabc31e-687f-503b-9951-d23086749580','b4ea0597-1b8b-56e8-aa6c-7da261fcf0b4','step',2,'Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('02dd1a67-d60a-52bf-bbdb-b764c610cd84','b4ea0597-1b8b-56e8-aa6c-7da261fcf0b4','step',3,'As you exhale, lift the handles up until your arms are fully extended overhead.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6a1569e4-a2ad-527f-9882-4fe39c7e1289','b4ea0597-1b8b-56e8-aa6c-7da261fcf0b4','cue',1,'Squeeze glutes and brace before pressing','en','ai_authored:pattern');
