INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6eae7d2b-8e51-5689-a21f-93fc37a83450','b4ea0597-1b8b-56e8-aa6c-7da261fcf0b4','mistake',3,'Flaring the ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1e056952-7929-5fc1-a4c1-3e068e27190e','e8904531-c41b-5a0b-b7fb-dad8884a05ed','step',1,'To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5d734391-e6ab-5cce-9da3-c37ad8548d69','e8904531-c41b-5a0b-b7fb-dad8884a05ed','step',2,'When holding the bands, they should be the same height on each side. This is the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4342cb26-7e16-5027-a08a-c3af3e43b89f','e8904531-c41b-5a0b-b7fb-dad8884a05ed','step',3,'Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e6d333a0-505e-5132-ab2c-9fb4d2944f70','e8904531-c41b-5a0b-b7fb-dad8884a05ed','step',4,'Use the heel of your feet to push your body up to the starting position as you exhale.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5d6d3322-a5c4-5088-b3ed-42c8b1012bb7','e8904531-c41b-5a0b-b7fb-dad8884a05ed','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db+fitbud_curated_edit');
