INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('064e78af-380f-5109-906a-63cd6885f62c','e8904531-c41b-5a0b-b7fb-dad8884a05ed','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('725c69b0-2cb0-5be1-9888-c974570b20b5','9a873446-0e9b-562d-a2e3-02aa1a273d4f','step',1,'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6227d6f2-2078-5c03-aab0-419dbf704e1b','9a873446-0e9b-562d-a2e3-02aa1a273d4f','step',2,'Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2fd62d6c-46e6-5f60-a8df-7c4d2b33b829','9a873446-0e9b-562d-a2e3-02aa1a273d4f','step',3,'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e0a080e3-8091-5fb7-a6b1-8e1b03bbd7cd','9a873446-0e9b-562d-a2e3-02aa1a273d4f','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3633eb43-e4ac-5063-b16a-3756633d8a63','9a873446-0e9b-562d-a2e3-02aa1a273d4f','cue',1,'Lead with the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('df6c9ef7-c1c7-5096-90dd-9d8772da6f4d','9a873446-0e9b-562d-a2e3-02aa1a273d4f','cue',2,'Control the lowering','en','ai_authored:pattern');
