INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ce08086e-5354-5ddc-aec2-a913b46c2396','a2a6be85-fde8-57f4-8ff0-d9698390fab8','step',1,'To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('de3e4438-d395-5fc4-a94b-198fe22dc2c6','a2a6be85-fde8-57f4-8ff0-d9698390fab8','step',2,'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d67fcc9-63f3-5e01-bbca-e80ebcb3dac7','a2a6be85-fde8-57f4-8ff0-d9698390fab8','step',3,'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1cb679b2-d0d9-548d-a5ec-85cc55964698','a2a6be85-fde8-57f4-8ff0-d9698390fab8','step',4,'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('19a9e53d-43f7-506e-887f-e3c9ed77a77b','a2a6be85-fde8-57f4-8ff0-d9698390fab8','step',5,'Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c46eb92f-2e7a-5785-80c0-f97e42672325','a2a6be85-fde8-57f4-8ff0-d9698390fab8','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db+fitbud_curated_edit');
