INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('14774cec-e91e-5a84-b77b-dae45585192c','4e567745-f548-5c0d-b5a7-aa897f98441c','step',1,'Begin seated on the ground with a loaded barbell over your legs. Roll the bar so that it is directly above your hips, and lay down flat on the floor.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7f0f8c43-cbf2-59c9-bbfc-83783b452a17','4e567745-f548-5c0d-b5a7-aa897f98441c','step',2,'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('25859b0f-8892-5032-b54e-288ab92080f9','4e567745-f548-5c0d-b5a7-aa897f98441c','step',3,'Extend as far as possible, then reverse the motion to return to the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('48b2cf3c-e9fc-53d2-a348-896c5feca9c0','4e567745-f548-5c0d-b5a7-aa897f98441c','cue',1,'Push your hips back, not down','en','ai_authored:pattern');
