INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2f6a5d7e-4cc5-55ce-bb67-be7595c6a375','8bfdd87c-d7d0-5636-860f-49f461c2dc49','step',1,'Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('381072dc-a404-5e35-a1d2-ee28cb452266','8bfdd87c-d7d0-5636-860f-49f461c2dc49','step',2,'As you breathe in, come down slowly until you feel the bar on you upper chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ee6d2dce-5da9-59ad-a0d9-c0f3d14b98d5','8bfdd87c-d7d0-5636-860f-49f461c2dc49','step',3,'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('494188ee-b00f-53cc-886e-65ddcbf4561c','8bfdd87c-d7d0-5636-860f-49f461c2dc49','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('699c9ceb-3e90-5865-bf50-8887e5846769','8bfdd87c-d7d0-5636-860f-49f461c2dc49','step',5,'When you are done, place the bar back in the rack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2ad6d83-6d89-5340-be70-33ea11bf9489','8bfdd87c-d7d0-5636-860f-49f461c2dc49','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
