INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dadd1081-0ba7-5a02-a673-341f8fa26c32','7b98027c-7e91-5644-8f2d-772a54a500a0','step',2,'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b2b8aa58-dabc-50e6-8b6f-ff98203f0a52','7b98027c-7e91-5644-8f2d-772a54a500a0','step',3,'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e72394b4-12dd-50d4-bc32-56a4dbc5a7a9','7b98027c-7e91-5644-8f2d-772a54a500a0','step',4,'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.','en','source:free_exercise_db+fitbud_curated_edit');
