INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('86f3a507-9315-5ee1-8742-a706e5a8a7e3','8667f449-7c4a-509d-8cbd-f54998b03fcd','step',2,'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Forearms should always be pointing down.','en','source:free_exercise_db+fitbud_curated_edit');
