INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('da1aff10-eb38-5778-a411-72815c442dd6','6eb6e252-05bb-5b44-ae4c-43609c25982d','step',3,'Lower the dumbbell in an arc behind your head until you feel a stretch in your chest.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('380aabef-760a-5247-a8b3-230cafb187ab','6eb6e252-05bb-5b44-ae4c-43609c25982d','step',4,'Push the dumbbell back over your chest along the same arc.','en','ai_authored:fitbud_curated');
