INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ff64c3ff-20ad-5dba-b76f-1dae093c4293','6eb6e252-05bb-5b44-ae4c-43609c25982d','cue',2,'Move in a wide arc','en','ai_authored:pattern');
