INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4e904c83-58eb-5e96-823f-e2a5308fff9a','710db63d-3636-5371-888c-fa181db61bf4','mistake',1,'Knees caving inward','en','ai_authored:pattern');
