INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1c4f8551-17c2-530e-abc0-d616c2df59ca','ecc8b20c-7110-56db-aa28-5e4c24c32768','step',2,'To begin, squat down be flexing your hips and knees until you can reach the handles.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('66d0798b-e46c-5ca4-ab78-09e506b2d80f','ecc8b20c-7110-56db-aa28-5e4c24c32768','step',3,'After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a71d7e7d-10e6-5ed1-90e5-42d70a60a025','ecc8b20c-7110-56db-aa28-5e4c24c32768','step',4,'After reaching a full standing position, Return to the starting position and repeat.','en','source:free_exercise_db');
