INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e2f17fff-393b-5e7a-ac12-c11bf7819577','a77b3d7a-9c90-55d9-a33a-7ceb5425acd2','step',2,'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62faefe5-4b5c-5fe3-a299-4adc92b9f919','a77b3d7a-9c90-55d9-a33a-7ceb5425acd2','step',3,'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. The forearms should do no other work other than hold the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a5ef4954-328d-5063-8675-f3a9876ee444','a77b3d7a-9c90-55d9-a33a-7ceb5425acd2','step',4,'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('697a5d2a-a072-54aa-aa03-e5797ac4e32d','a77b3d7a-9c90-55d9-a33a-7ceb5425acd2','step',5,'Repeat this motion for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2e1eac7-6679-5e3c-80c7-488afa809370','a77b3d7a-9c90-55d9-a33a-7ceb5425acd2','cue',1,'Start each rep by pulling the shoulder blades down','en','ai_authored:pattern');
