INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35f41bba-85d7-561f-a034-cd6c48dd7f50','0af699a7-90ad-5aa2-9224-71e99df54b25','step',2,'As you breathe in, come down slowly until you feel the bar on your middle chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('596e114f-4406-534b-a4b4-b63e0a3f177c','0af699a7-90ad-5aa2-9224-71e99df54b25','step',3,'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('98daded8-32b3-5487-8184-bfcfbda5a495','0af699a7-90ad-5aa2-9224-71e99df54b25','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
