INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8091ea80-7719-560d-811e-554322ccda1c','861133c6-68b5-577a-bef4-37908a874efc','step',2,'To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b1001436-7c79-5339-a0f2-39685198d79d','861133c6-68b5-577a-bef4-37908a874efc','step',3,'After a brief pause, return to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aefdc9e7-5eb9-577a-8e1b-809765fe4360','861133c6-68b5-577a-bef4-37908a874efc','cue',1,'Exhale as you curl up','en','ai_authored:pattern');
