INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2069685f-471f-5e06-ae2a-1ba49a8236bb','a9259855-671b-5b3c-8c7f-7e03bf70f8de','step',1,'Stand with your feet shoulder width apart. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0232008d-1f6f-5f3e-a71c-833b8d323530','a9259855-671b-5b3c-8c7f-7e03bf70f8de','step',2,'Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7516f7be-6673-5b4a-addc-ab3d3c0b960c','a9259855-671b-5b3c-8c7f-7e03bf70f8de','step',3,'After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7e09f9d-9eea-5705-ab89-0b7d52acaf93','a9259855-671b-5b3c-8c7f-7e03bf70f8de','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
