INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a8ca83e5-ec9e-54cb-8586-96f92ab1ccf4','28b6c147-d423-5f32-81b4-875f8db37c76','step',1,'Lie on your back with your knees bent and feet flat.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b4a3f41f-1948-5cf4-b5f9-ef3b0a92aed1','28b6c147-d423-5f32-81b4-875f8db37c76','step',2,'Brace your core and press your lower back gently into the floor.','en','ai_authored:fitbud_curated');
