INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7936fd62-be07-5d9a-9a1c-3cf0c98b1591','0bc0ba5f-3493-56cd-b94e-2a8dde78420b','step',2,'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('28f11ed1-a37b-5a05-8063-8afbfe42f144','0bc0ba5f-3493-56cd-b94e-2a8dde78420b','step',3,'As you breathe in, come down slowly until you feel the bar on your lower chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f3f5c424-72ee-5aab-bc1d-1e0d435b66dd','0bc0ba5f-3493-56cd-b94e-2a8dde78420b','step',4,'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8ee72c51-a2e7-5c36-a590-fa04f1bb44b7','0bc0ba5f-3493-56cd-b94e-2a8dde78420b','step',5,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('40456684-6a1a-5dd5-93c0-c7492e58d6b6','0bc0ba5f-3493-56cd-b94e-2a8dde78420b','step',6,'When you are done, place the bar back in the rack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6aec2ea5-d182-5584-8e19-0246b9139e32','0bc0ba5f-3493-56cd-b94e-2a8dde78420b','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
