INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('103dacc8-7f68-5400-9115-c18a1f87cf24','c5d25432-6806-50c7-9ecf-39f61b363c02','step',1,'Secure your legs at the end of the decline bench and lie down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c4735872-ce52-54f0-8414-60158ef3f2d4','c5d25432-6806-50c7-9ecf-39f61b363c02','step',2,'Now place your hands lightly on either side of your head keeping your elbows in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9458a253-d5d2-562b-b861-2f2c6c3de60b','c5d25432-6806-50c7-9ecf-39f61b363c02','step',3,'While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2a5ff241-ddc2-5a6e-bb47-0b4f42a99d47','c5d25432-6806-50c7-9ecf-39f61b363c02','step',4,'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('80ab0250-14ee-5a3f-a2bd-9afd738891c7','c5d25432-6806-50c7-9ecf-39f61b363c02','step',5,'After the one second contraction, begin to come down slowly again to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0576e0a1-9ddc-55f0-95d0-f5e610dc8621','c5d25432-6806-50c7-9ecf-39f61b363c02','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
