INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('afc99385-dade-5e1f-8ab6-0dfa41febe01','069adb1e-6542-5d92-a14b-e01cef6e338f','step',1,'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','en','source:free_exercise_db');
