INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('edf26d7d-1840-5b83-b3db-a5a6124a6044','98da6598-f147-5a82-ad16-229ec533cd31','step',1,'Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('40f02e84-33ed-523b-b334-8af3877875a3','98da6598-f147-5a82-ad16-229ec533cd31','step',2,'Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c47607f-6050-5049-83eb-e6641c6dc10d','98da6598-f147-5a82-ad16-229ec533cd31','step',3,'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f5a1add9-9472-594e-bb01-24df38ced4f3','98da6598-f147-5a82-ad16-229ec533cd31','step',4,'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9f37a8ac-d7be-565a-8332-4064299eed8b','98da6598-f147-5a82-ad16-229ec533cd31','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db+fitbud_curated_edit');
