INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac70566f-e011-564a-83e3-2e7f1a0cadb0','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',1,'Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e0727ad6-ad2c-5bec-bc20-b5cef5b32f16','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',2,'While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d5e8e330-ab5b-5064-a4a3-d2c12b6f2ec9','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',3,'Slowly begin to bring the dumbbell back to the starting position as your breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2f0942a2-1c5f-5e82-880d-efa72850ebe8','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',4,'Repeat the movement with the left hand. This equals one repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35196a0c-da69-59a4-9be8-a2169beb2fc6','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',5,'Continue alternating in this manner for the recommended amount of repetitions.','en','source:free_exercise_db');
