INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c94697a4-870d-5295-95fd-b73f749cb83d','69b2567d-97cb-5839-8a26-17169ebefe14','step',1,'Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bc0db545-f53e-57a3-ac78-a9f787e045c4','69b2567d-97cb-5839-8a26-17169ebefe14','step',2,'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b7ffc801-f75a-5cd2-aa3f-dfe030fab9ef','69b2567d-97cb-5839-8a26-17169ebefe14','step',3,'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('adc98378-f94a-5cd9-b90d-b42e56902198','69b2567d-97cb-5839-8a26-17169ebefe14','step',4,'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be7131ad-a624-5f34-8e49-5a09b45b4f51','69b2567d-97cb-5839-8a26-17169ebefe14','step',5,'Repeat the movement for the prescribed amount of repetitions of your training program.','en','source:free_exercise_db');
