INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e21bebef-ba6c-5233-80ee-b373848bfbfe','28cec5e7-ed8f-5327-86d9-f7553b4a93cc','step',1,'Begin standing with a dumbbell in each hand with your feet shoulder width apart.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('02daee95-8a40-55b1-b31d-9b5168025f2d','28cec5e7-ed8f-5327-86d9-f7553b4a93cc','step',2,'Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3e2323f2-1975-5bf0-a21e-f8e4f1ec1377','28cec5e7-ed8f-5327-86d9-f7553b4a93cc','step',3,'To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('98acbcf3-413d-5711-b101-cc42e283e6a9','28cec5e7-ed8f-5327-86d9-f7553b4a93cc','step',4,'After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ace11d86-11d6-5d8f-abfb-38f55043ed40','28cec5e7-ed8f-5327-86d9-f7553b4a93cc','step',5,'Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d7ab9499-40c5-54bc-9a94-62d61ebb6d3a','28cec5e7-ed8f-5327-86d9-f7553b4a93cc','cue',1,'Drive explosively with the legs/hips','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0aba5c63-350e-5e22-9de2-3efa3db88f51','28cec5e7-ed8f-5327-86d9-f7553b4a93cc','cue',2,'Keep the load close','en','ai_authored:pattern');
