INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f45d712b-f7f7-5ba2-9449-fdec6bf725b9','67960ba9-2a2d-56a2-8e8f-240cbfbbec30','step',1,'Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cdc1b714-b4aa-5705-943b-7d2948f50f09','67960ba9-2a2d-56a2-8e8f-240cbfbbec30','step',2,'Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e6ed47f8-450d-5a89-932a-7910afbed730','67960ba9-2a2d-56a2-8e8f-240cbfbbec30','step',3,'Pause at the bottom, and then bring the weight together at the top by extending through the elbows.','en','source:free_exercise_db');
