INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1ab8fae0-fe72-5234-8468-5691944f81ae','34001892-c69e-5413-bdc1-ca9b407d0a0f','step',4,'Pause, then let your arms straighten slowly without rounding forward.','en','ai_authored:fitbud_curated');
