INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4d6b3079-540e-52aa-b7df-de46f0848eff','f225ed9d-de1c-52df-9123-543a269711e2','step',2,'Now place your lower shins on top of an exercise ball. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b82d6248-1a9a-583b-8583-3c807de59a6f','f225ed9d-de1c-52df-9123-543a269711e2','step',3,'While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('832d3064-ba5e-5ec2-8dc7-efe208610ae0','f225ed9d-de1c-52df-9123-543a269711e2','step',4,'Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.','en','source:free_exercise_db');
