INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2052e563-3c1c-596d-bf2f-107bcfb214c5','a16ee156-75d5-5d74-81f0-5e28ee48fe25','step',2,'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0b708927-47ad-52db-9446-18b977c5dd35','a16ee156-75d5-5d74-81f0-5e28ee48fe25','step',3,'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('666d52ad-fe16-5160-b68f-01deaacb6ef4','a16ee156-75d5-5d74-81f0-5e28ee48fe25','step',4,'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.','en','source:free_exercise_db');
