INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('13892821-d9d0-5f2b-bb7b-cac0605dc577','e0fd3b18-e7b6-5035-afdf-1c6a9c799092','step',1,'Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9dce7eb8-f33d-5376-86cc-510bfc5e5efe','e0fd3b18-e7b6-5035-afdf-1c6a9c799092','step',2,'Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0de732e5-685a-5f03-b596-2eb616c480ac','e0fd3b18-e7b6-5035-afdf-1c6a9c799092','step',3,'Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a9b3ec52-511f-590b-aaca-40c9370f7147','e0fd3b18-e7b6-5035-afdf-1c6a9c799092','step',4,'Then inhale and slowly lower the bar back to the starting position.','en','source:free_exercise_db');
