INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1af7778a-b604-5684-8a99-1d000e7747e1','f1cb49e2-8f2b-5184-97b1-28e7b365a23e','step',2,'Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('63dcb88e-0495-501c-955a-669f1b6d67f4','f1cb49e2-8f2b-5184-97b1-28e7b365a23e','step',3,'As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('93f84804-6edf-5c11-9a27-2c53922654c2','f1cb49e2-8f2b-5184-97b1-28e7b365a23e','step',4,'Now, as you inhale, slowly lower your legs back down to the starting position.','en','source:free_exercise_db');
