INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3512e7bf-4b94-50b1-895d-087d9a05a1ac','708d69fa-371e-5cac-bb7a-42c7fa0dd598','step',2,'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a573fab3-fced-548e-815f-3117711df1e3','708d69fa-371e-5cac-bb7a-42c7fa0dd598','step',3,'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.','en','source:free_exercise_db');
