INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bd991452-0447-5b3f-a5e4-9ee196a42ae9','070b6e34-c68b-578e-b708-a393adab3946','step',1,'Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('331d9213-1831-569b-a2f7-87bf8f8cd1cd','070b6e34-c68b-578e-b708-a393adab3946','step',2,'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('70b63051-5938-598d-a0cf-3279392729f9','070b6e34-c68b-578e-b708-a393adab3946','step',3,'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.','en','source:free_exercise_db');
