INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0f21c807-8eed-5653-86ff-4d0da5082e5f','eeb00a32-a5ea-57e4-878b-3b197e3bc299','cue',2,'Move into the stretch gradually','en','ai_authored:pattern');
