INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('73dfc5b4-e071-5121-85e3-092fc1ca61af','d5ffd4b6-d501-5f65-92cd-0df364b8364f','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1ec182ac-44a5-5f38-b85e-5973e0240f17','bd39fc76-75ad-5d77-a881-89d1aa220657','step',1,'Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e3926ae5-d679-54a3-ae44-b0867ce52bd2','bd39fc76-75ad-5d77-a881-89d1aa220657','step',2,'The palms of the hands should be facing your torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8cf51ad2-1a82-514b-b9ae-80edfc83b9a6','bd39fc76-75ad-5d77-a881-89d1aa220657','step',3,'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5ead533b-16dd-532c-8e5f-77eedf0d6de1','bd39fc76-75ad-5d77-a881-89d1aa220657','step',4,'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ed4d7443-0332-5f25-bb02-3645b761473a','bd39fc76-75ad-5d77-a881-89d1aa220657','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
