INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c09235f4-7a71-5670-8c25-7dffdca47c45','bd39fc76-75ad-5d77-a881-89d1aa220657','cue',2,'Squeeze at the top','en','ai_authored:pattern');
