INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('03bb019a-5a9f-566c-ad58-71bab8e4bce2','eb95a1f8-c816-58b7-9960-d47467ad3bf4','step',2,'Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0d05e033-ed44-556c-aa55-5243bebae3e1','eb95a1f8-c816-58b7-9960-d47467ad3bf4','step',3,'Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg.','en','source:free_exercise_db');
