INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('832246c3-f6fb-54d7-8a35-a300a7e1aa18','dfa54e1a-888c-56d4-a105-1042ba0fee0a','step',2,'Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Also, make sure that you keep facing the wall with your head, rather than looking down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('114694e2-9a72-5a7f-9522-71efb8406a82','dfa54e1a-888c-56d4-a105-1042ba0fee0a','step',3,'Slowly lower yourself to the ground as you inhale until your head almost touches the floor.','en','source:free_exercise_db');
