INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fa56fdff-480d-5ce6-a0b2-4d34d706147e','f9de6117-9040-5019-8bf1-9af847bf909b','step',1,'With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8598cbd7-0b81-5019-aea9-bc4c04458402','f9de6117-9040-5019-8bf1-9af847bf909b','step',2,'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0f8914ae-6e84-557e-b105-8bf8511dbbb0','f9de6117-9040-5019-8bf1-9af847bf909b','step',3,'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3fc6b3c2-4d48-5577-aebe-5edae5af6055','f9de6117-9040-5019-8bf1-9af847bf909b','step',4,'Slowly raise your torso back to the initial position as you exhale. Also, do not swing the torso at any time in order to protect the back from injury.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0dc631c6-dd34-59e1-8910-0687bac2f0b8','f9de6117-9040-5019-8bf1-9af847bf909b','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
