INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a3a3267d-6579-55a2-af04-e7b335e1f506','af8dd64f-225f-5b26-a878-4cdd6f0bd51e','step',2,'Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d40a549a-a97c-580d-ac0f-1d3b4745b43b','af8dd64f-225f-5b26-a878-4cdd6f0bd51e','step',3,'Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.','en','source:free_exercise_db');
