INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0337379d-a825-5328-be71-b5bea2b8615c','6214ce32-c8f7-5fce-9d9c-71d5383d49eb','step',2,'Hold the cable handles with your arms out wide and elbows slightly bent.','en','ai_authored:fitbud_curated');
