INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9b59de71-74df-5e46-bd48-b2076407c3d6','8c19a934-f679-517d-aa37-2bf589965d2f','step',2,'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fe7ee953-02f2-5464-80b8-4032f4203a21','8c19a934-f679-517d-aa37-2bf589965d2f','step',3,'Slowly begin to bring the dumbbells back to starting position as your breathe in.','en','source:free_exercise_db');
