INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1f7ddd6e-3c6b-5bb8-b37b-8aa82901928d','c7b0d125-bae1-5159-b435-9c6ea1070133','step',2,'Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.','en','source:free_exercise_db');
