INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('53d7fa49-6e6a-5db7-ba28-e347c8e65450','95984c7f-d04f-5638-af7c-20338f1898e3','step',4,'After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.','en','source:free_exercise_db');
