INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('688b9234-f114-5fe1-b353-e12bf9529b53','f1a38ae0-4966-57ea-af66-77895e149223','step',2,'Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a66a4f06-9f7a-5530-a303-2985e6f05421','f1a38ae0-4966-57ea-af66-77895e149223','step',3,'Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. The upper arms should remain stationary and on the pad at all times.','en','source:free_exercise_db');
