INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d8a3076-7dde-5e76-95b5-c80a8cf99679','d52984d3-ed7e-5308-97f8-5594d7afa0f2','step',3,'Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a3522445-fc41-5764-bde8-96406c635098','d52984d3-ed7e-5308-97f8-5594d7afa0f2','step',4,'Your partner should catch the ball, and throw it back to you.','en','source:free_exercise_db+fitbud_curated_edit');
