INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6427f678-c0a8-5916-a74a-2a736f031a29','63cba2c8-d3aa-56de-ba09-7bc7881c0a93','step',1,'Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('89cabfae-a9d7-5821-934e-f7f5ca4fbed1','63cba2c8-d3aa-56de-ba09-7bc7881c0a93','step',2,'Now start to pull yourself up as you exhale. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('03a127b7-3c81-5eb6-87e4-fe565d709c96','63cba2c8-d3aa-56de-ba09-7bc7881c0a93','step',3,'After a second contraction at the top, start to slowly come down as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6c4ef33a-4a2e-5cac-bfc1-0fe3578c87a5','63cba2c8-d3aa-56de-ba09-7bc7881c0a93','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
