INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a996cf17-4447-5989-9b3f-e10bffa0936b','fb7d73a1-182f-5d09-8be6-4ab4fd892560','step',2,'Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.','en','source:free_exercise_db');
