INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b10cd791-f840-5869-8c2b-eff272728db0','0e625ce1-2fc8-50ad-83ef-a26e7402fb1d','step',1,'Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('65f825db-4e4e-5edb-af4d-9480b407ef5e','0e625ce1-2fc8-50ad-83ef-a26e7402fb1d','step',2,'Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d7133ab-7214-573a-8c7f-2a778235a128','0e625ce1-2fc8-50ad-83ef-a26e7402fb1d','step',3,'Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1ab984b9-2fbd-598d-a85f-fb95da27d931','0e625ce1-2fc8-50ad-83ef-a26e7402fb1d','step',4,'Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6a3f6497-70bc-5e7a-8add-8247cb54c661','0e625ce1-2fc8-50ad-83ef-a26e7402fb1d','step',5,'Now use your feet and legs to help bring the weight back up to the starting position while exhaling.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f4d47915-9aac-566d-8f5a-19bd14db8bc8','0e625ce1-2fc8-50ad-83ef-a26e7402fb1d','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
