INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('44ed3098-c499-5118-b96c-d4c81c260ec1','c3add3b5-045a-522e-ab33-33c19cf0c555','step',1,'Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c9d1b004-7bee-5692-9e10-7e122ad7f3d3','c3add3b5-045a-522e-ab33-33c19cf0c555','step',2,'With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4b5af6e6-bca1-5148-9433-2be8c48f1df2','c3add3b5-045a-522e-ab33-33c19cf0c555','step',3,'With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('52394daf-cb9a-591e-8f68-24df8fb4d605','c3add3b5-045a-522e-ab33-33c19cf0c555','step',4,'Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.','en','source:free_exercise_db');
