INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('451ffcc3-6f47-5513-9718-d623b493d85c','d8a555e3-a2ea-57ea-93db-ebf1e1973d5f','step',2,'Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6f1e4220-3c4d-52da-b5dc-aa2c7d6e9983','d8a555e3-a2ea-57ea-93db-ebf1e1973d5f','step',3,'Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.','en','source:free_exercise_db+fitbud_curated_edit');
