INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9d7597e-a324-525a-8b89-ea3ef9b40147','cc934012-55ea-5984-9aa9-6ff3ec427ea7','step',2,'Your toes should be facing out. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b3fcba22-358d-5304-82c7-5f3c59533955','cc934012-55ea-5984-9aa9-6ff3ec427ea7','step',3,'Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2838e654-db0f-5f14-8a31-463a3f46979d','cc934012-55ea-5984-9aa9-6ff3ec427ea7','step',4,'Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.','en','source:free_exercise_db');
