INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('02d46dea-b025-5567-96d1-d95ec3bd50b4','b6d28e60-640c-5dec-b895-96f7bff2d858','step',2,'Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be80cca2-02dc-5477-87be-199907b4be56','b6d28e60-640c-5dec-b895-96f7bff2d858','step',3,'Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6e7c4e0b-3f88-573e-9e69-3de28abb35ab','b6d28e60-640c-5dec-b895-96f7bff2d858','step',4,'Lower the arm back to the floor for another pushup and then twist to the other side.','en','source:free_exercise_db');
