INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ff9d768-b73b-55d7-ad17-aa0f46cab2b9','f8f66b40-b70b-58ba-9819-823bed5454e8','step',2,'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.','en','source:free_exercise_db');
