INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('627d632d-a332-5784-a69c-a30c47c7fb70','d2a2e034-0e9b-592c-9d3f-19a63b0ed156','step',1,'Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cf708cb9-590f-58a6-ae83-a79122122517','d2a2e034-0e9b-592c-9d3f-19a63b0ed156','step',2,'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ad677321-3f66-5505-9e19-c9a9b270d799','d2a2e034-0e9b-592c-9d3f-19a63b0ed156','step',3,'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62b00654-d5a5-5c9d-934a-350f2c0cbf64','d2a2e034-0e9b-592c-9d3f-19a63b0ed156','step',4,'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ae1bf11f-9682-5fd2-bad7-2ba49b907422','d2a2e034-0e9b-592c-9d3f-19a63b0ed156','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f5a1e593-6a0a-5463-8160-288870df38e6','d2a2e034-0e9b-592c-9d3f-19a63b0ed156','cue',1,'Keep upper arms still','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('efb109b7-716f-52c7-8217-db9dd5506e85','d2a2e034-0e9b-592c-9d3f-19a63b0ed156','cue',2,'Fully straighten the elbow','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b738321c-5aef-5662-8f7c-f887df1935a5','d2a2e034-0e9b-592c-9d3f-19a63b0ed156','cue',3,'Control the stretch','en','ai_authored:pattern');
