INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('10d7018d-c494-552b-ae9b-bc10469f46a9','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','step',2,'By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.','en','source:free_exercise_db');
