INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('61a8ac63-087a-53e4-a791-93409c72e882','ddb18f4b-713b-52a2-88a1-32122ee1f0fc','step',3,'Return to the starting position without letting the weight stop, keeping tension on the muscle.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6b0c89e6-a379-5195-be57-12a8509026b2','ddb18f4b-713b-52a2-88a1-32122ee1f0fc','step',4,'Repeat for the desired number of repetitions.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cdd5a241-3a53-5476-a015-12b0a5c0ee21','ddb18f4b-713b-52a2-88a1-32122ee1f0fc','step',5,'Finish all reps on one side, then switch sides and repeat.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e15bad01-e402-506b-a3c1-5323a56013ef','ddb18f4b-713b-52a2-88a1-32122ee1f0fc','cue',1,'Pause briefly at the top','en','ai_authored:pattern');
