INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87898b97-a689-5d67-ba58-3bc43b730c2b','36dcd5d7-ad5b-5fdc-adb8-fbba8587ed47','step',2,'Cross your arms over your chest.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('23b32ed2-f731-5c6d-9463-abdab218beb3','36dcd5d7-ad5b-5fdc-adb8-fbba8587ed47','step',3,'Curl your torso up until you are sitting tall.','en','ai_authored:fitbud_curated');
