INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6fa06808-6452-55d4-9a90-8ef51f2804a8','afce8de9-fef2-557d-a25d-1f370e1b1ed1','step',1,'Stand under the Smith machine bar with the balls of your feet on a raised edge.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('775b0281-418c-5219-8fa0-2c89a8e4b134','afce8de9-fef2-557d-a25d-1f370e1b1ed1','step',2,'Lower your heels slowly below your toes for a full stretch.','en','ai_authored:fitbud_curated');
