INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('41219620-a497-5c07-802a-af0af5643acf','e9047eae-d133-52ef-adaf-441e48b9d299','step',1,'Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fbf277fd-4546-58b3-8184-3c0d4bf1be06','e9047eae-d133-52ef-adaf-441e48b9d299','step',2,'As you breathe in, come down slowly until you feel the bar on your upper chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d096ac0a-e398-5407-8741-04abf8e84a17','e9047eae-d133-52ef-adaf-441e48b9d299','step',3,'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('03be5b72-770c-5cdb-86eb-5dc07982548d','e9047eae-d133-52ef-adaf-441e48b9d299','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aba46f7d-dbee-58bf-9e7e-e696da26c9e9','e9047eae-d133-52ef-adaf-441e48b9d299','step',5,'When you are done, place the bar back in the rack.','en','source:free_exercise_db');
