INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1b71c2ee-be1a-5a62-a461-6da65041eeb0','c50a4b74-054a-5889-aa47-5f00aa9a72ad','step',1,'Stand tall with your feet about hip-width apart.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('22f33150-8c08-57c6-9b9e-29d489293de4','c50a4b74-054a-5889-aa47-5f00aa9a72ad','step',2,'Hold the Smith machine bar at shoulder height.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('70a77191-ef12-5c37-a89b-f771c441dc75','c50a4b74-054a-5889-aa47-5f00aa9a72ad','step',3,'Brace your core and press the Smith machine bar straight overhead until your arms are straight.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc87124c-1513-5984-bd44-b1fcb4c9312d','c50a4b74-054a-5889-aa47-5f00aa9a72ad','step',4,'Lower the Smith machine bar under control back to shoulder height.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('57559f3f-690c-5712-a588-5bd9726ee8e3','c50a4b74-054a-5889-aa47-5f00aa9a72ad','cue',1,'Squeeze glutes and brace before pressing','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fbf4f6ff-11b3-5d14-8404-e41704ac77d4','c50a4b74-054a-5889-aa47-5f00aa9a72ad','cue',2,'Press in a straight line overhead','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0dd91dd6-ec81-52ab-94d7-1d382abfdb02','c50a4b74-054a-5889-aa47-5f00aa9a72ad','cue',3,'Finish with biceps near the ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7f73fbc-7d6a-57ce-b005-ff7c90c5f33d','c50a4b74-054a-5889-aa47-5f00aa9a72ad','mistake',1,'Excessive lower-back arch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a54922f6-1a0b-5e03-a27a-63fcd4f9730c','c50a4b74-054a-5889-aa47-5f00aa9a72ad','mistake',2,'Pressing forward instead of up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('df7015c0-9c97-5877-9733-2cb96f021196','c50a4b74-054a-5889-aa47-5f00aa9a72ad','mistake',3,'Flaring the ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ab244c3-80b7-5634-853a-f79208dd4b1d','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','step',1,'To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0fe00b04-b72f-566a-907c-e04d6165dff8','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','step',2,'Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('55fc1309-7d7f-54cf-8331-c064e6991c99','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','step',3,'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('33f4b4a4-6532-556d-a065-ded1cda2d18c','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','step',4,'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('579b6075-5b02-56e5-9b42-2acd921ab1da','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','step',5,'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9d1308d7-c0ae-56ef-b4ae-e2b6270385c2','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c78e5b87-8e6f-5b1a-805a-037b1f6b1976','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','cue',1,'Brace your core before you descend','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ae052a82-7a66-5cf9-bc1e-3f0a00946223','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','cue',2,'Knees track over your toes','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2657454e-3def-51de-8b30-f42cdcfeab7e','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4067a594-229a-5880-8101-44fd1ee8170d','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','mistake',1,'Knees caving inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc8944b0-4ac6-578e-bc4d-171ae5f3f71c','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','mistake',2,'Heels lifting off the floor','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2db75e3b-a36b-5168-ae5e-2258bfb6ce6e','39fe47b1-cdc7-5088-b4a7-abb5c681cf1d','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6f08fdf2-4a11-55c5-83db-843c38661d32','835309e0-e7b4-51e2-b852-6b65b20ea3f7','step',1,'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dc22fdc0-a901-5a9a-958c-753a724dd73c','835309e0-e7b4-51e2-b852-6b65b20ea3f7','step',2,'Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d663e336-768c-5336-93a6-f4c63dcd12b6','835309e0-e7b4-51e2-b852-6b65b20ea3f7','step',3,'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('61242ed5-b3d2-52c9-a756-c15c69a024de','835309e0-e7b4-51e2-b852-6b65b20ea3f7','step',4,'Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c0e28eae-7538-5fd6-897a-010af9d3edad','835309e0-e7b4-51e2-b852-6b65b20ea3f7','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ebb16637-3c9c-5ded-a9d7-8775a0761fbb','835309e0-e7b4-51e2-b852-6b65b20ea3f7','cue',1,'Push your hips back, not down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3b0e3ea2-927d-5044-9e56-99e7c72f1415','835309e0-e7b4-51e2-b852-6b65b20ea3f7','cue',2,'Keep the weight close to your legs','en','ai_authored:pattern');
