INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6f65c4a3-0122-5ad0-82d3-8bb94984bea3','835309e0-e7b4-51e2-b852-6b65b20ea3f7','mistake',2,'Turning the hinge into a squat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c55f71d9-3f0f-5759-83cd-beabe7b7a0b0','835309e0-e7b4-51e2-b852-6b65b20ea3f7','mistake',3,'Hyperextending at lockout','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b48b0ea3-26de-51c7-b8ca-bb30996d4346','93aadd22-bb02-577f-8508-d351a985cb62','step',1,'Set the Smith machine bar across your upper back, working on one leg at a time.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('adfc639d-a981-57d2-b93c-59e7d1f0881a','93aadd22-bb02-577f-8508-d351a985cb62','step',2,'Take a long split stance with your back heel lifted.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e434b1de-7ca1-5e79-83b1-905d5103520f','93aadd22-bb02-577f-8508-d351a985cb62','step',3,'Lower your back knee straight down toward the floor until your front thigh is about parallel.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('360d2ead-5155-50cd-8187-cf9a96721322','93aadd22-bb02-577f-8508-d351a985cb62','step',4,'Drive through your front foot to rise back up.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('36fc97c7-8e37-5e9c-b7b9-2049da05de88','93aadd22-bb02-577f-8508-d351a985cb62','step',5,'Finish all reps on one side, then switch legs.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4eac5aea-d4c8-5264-bfe9-88d1431b10ba','93aadd22-bb02-577f-8508-d351a985cb62','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('430c56bb-17d9-5c53-a332-8b0952e8b210','93aadd22-bb02-577f-8508-d351a985cb62','cue',2,'Lower the back knee straight down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2cdd537b-4eb7-5ac8-ad30-1106b81f300a','93aadd22-bb02-577f-8508-d351a985cb62','cue',3,'Keep your torso tall','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7e79cad3-abe2-5b07-be02-8c63377efa0e','93aadd22-bb02-577f-8508-d351a985cb62','mistake',1,'Front knee collapsing inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e4c29a7e-d93a-5f15-af78-f023e217621f','93aadd22-bb02-577f-8508-d351a985cb62','mistake',2,'Pushing off the back foot instead of the front heel','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('57ac4638-59fd-57c7-a787-388e8c520ad8','93aadd22-bb02-577f-8508-d351a985cb62','mistake',3,'Short, choppy steps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('69f0b68e-3ad6-5c02-b925-f15d70f73e06','9a031b91-d55c-5bd4-8976-be8f1687d3ad','step',1,'Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c3ed983-6e86-562d-a84e-89547ec5d75b','9a031b91-d55c-5bd4-8976-be8f1687d3ad','step',2,'Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.','en','source:free_exercise_db');
