INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f1c16177-193a-56f0-b4ad-3fa127201e7a','ec3a9d89-7dab-53cf-b81b-81d701929e20','step',4,'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.','en','source:free_exercise_db');
