INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c693eaa7-edc5-5a39-898c-9ea8f6894c5d','68818dbc-48c8-5a53-8fbd-02832153a3c9','step',2,'Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Breathe in as you perform this step.','en','source:free_exercise_db');
