INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2bf912ed-0785-5218-a87b-8a7a4ca7c85a','8d5d029a-5d93-5581-b979-5d28ca771881','step',2,'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Allow your elbows to point out. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bf1b91a3-6c09-55ef-97fa-e054a7118fe8','8d5d029a-5d93-5581-b979-5d28ca771881','step',3,'Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e387b492-e604-5164-9c0f-fbd758838c33','8d5d029a-5d93-5581-b979-5d28ca771881','step',4,'As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('71806d3b-3c51-54af-b68a-bf6d00e0df63','8d5d029a-5d93-5581-b979-5d28ca771881','step',5,'Repeat the movement for the prescribed amount of repetitions of your training program.','en','source:free_exercise_db');
