INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('398084d6-a57c-5342-b537-b40489255151','c6424eeb-6b8f-5a89-8f48-1492c2b29f70','step',1,'Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d0054e4c-c920-51e2-ae41-5377b4b2ac31','c6424eeb-6b8f-5a89-8f48-1492c2b29f70','step',2,'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d0071431-4ac2-538e-bdd2-87e2483048a0','c6424eeb-6b8f-5a89-8f48-1492c2b29f70','step',3,'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1699efd6-5cf5-5db8-bdf2-51b0a7b1f22e','c6424eeb-6b8f-5a89-8f48-1492c2b29f70','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
