INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ec61c74c-0753-57ba-9292-e586713df618','1d3441fc-6f01-504e-a583-b73eee60de7d','step',1,'Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a383437f-1091-5a19-90fa-6d0e9d3d726c','1d3441fc-6f01-504e-a583-b73eee60de7d','step',2,'Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bbe1ea58-dae5-53da-9958-192405fc4b8c','1d3441fc-6f01-504e-a583-b73eee60de7d','step',3,'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.','en','source:free_exercise_db');
