INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('45392a71-6eb6-535d-9cd9-01615052ba4e','4e8a72f6-fdb8-5dd6-b021-33bd1ff3ed3b','step',2,'Grip the V-bar with your hands a little wider than your shoulders.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('98303d91-aa16-5fb6-a01b-95a0ece274b6','4e8a72f6-fdb8-5dd6-b021-33bd1ff3ed3b','step',3,'Pull the V-bar down to your upper chest, driving your elbows toward your ribs.','en','ai_authored:fitbud_curated');
