INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('073c5691-79b5-5781-8e91-34d8112d22e9','bddefee3-127f-52fa-92a1-b705be120407','step',1,'Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e0cafa69-46e2-5b62-a474-879fe2d82a82','bddefee3-127f-52fa-92a1-b705be120407','step',2,'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bc96e3c1-61ad-507d-b815-5213951f3eaa','bddefee3-127f-52fa-92a1-b705be120407','step',3,'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a3c57d12-c02f-5f3f-a9ec-b2da04edf15d','bddefee3-127f-52fa-92a1-b705be120407','step',4,'After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7619bf0c-dd11-527b-92cc-45acea706e54','bddefee3-127f-52fa-92a1-b705be120407','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
