INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('25773bc2-427a-5194-99ec-ee54b38ab172','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','step',1,'Stand with your back flat against a wall and your feet about two feet in front of you.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1e5992b5-a2b9-57a2-b87a-79ee7fdbff6f','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','step',2,'Slide down until your knees are bent to about 90 degrees.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f1532294-01b7-5d28-8f9d-436882d136cb','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','step',3,'Hold the position with your weight in your heels.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a9dd581-7d16-55bc-be40-74577f796ee7','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','step',4,'Push through your heels to slide back up the wall.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('57c57e72-da1e-50c4-b033-e41f2fec2154','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','cue',1,'Knees over ankles','en','ai_authored:specific');
