INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ee728699-96f7-57ad-806b-b0dd25a91eaa','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','mistake',2,'Hands pushing on thighs','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aab85fcd-be76-5cbc-8dbd-7c320dacf28e','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','mistake',3,'Holding breath','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('604a3230-3e2e-5c77-9f80-e781a9884bb8','cc0092e1-fcaa-58ac-b56f-4cd62d9a7c52','step',1,'Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1950fb73-dec2-59f6-9915-7b713819a320','cc0092e1-fcaa-58ac-b56f-4cd62d9a7c52','step',2,'You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d0481dc3-3626-5243-a736-7484d60671e1','cc0092e1-fcaa-58ac-b56f-4cd62d9a7c52','step',3,'Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5b59a04b-3556-5bef-a8a6-47a21d2d46d8','cc0092e1-fcaa-58ac-b56f-4cd62d9a7c52','step',4,'After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2d9f699a-42a2-58f8-9bcc-8f4d38af0707','cc0092e1-fcaa-58ac-b56f-4cd62d9a7c52','cue',1,'Start each rep by pulling the shoulder blades down','en','ai_authored:pattern');
