INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ae7e2be4-8e79-5b87-9693-7fa839ec8cfa','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','step',1,'With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cf117960-6308-56ec-a3b3-f363d5a647db','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','step',2,'To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0701ae99-629a-56f3-a6ec-aa02f37105cf','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','step',3,'Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('beccd970-500e-525a-879c-8af774d9078d','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','step',4,'After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('326c5473-cbbc-5018-8575-dad7f3ae232d','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7cf2c83d-f410-5269-b66d-7a098b54965c','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','cue',2,'Wrists stacked over elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8167955c-da49-5191-98e1-3365c3b1bc02','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','cue',3,'Lower under control to chest level','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b02776ca-c698-5578-bc65-45dd1acf3508','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','mistake',1,'Flaring elbows to 90 degrees','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('058a61c1-5b48-5f20-9086-670d7b800437','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','mistake',2,'Bouncing off the chest','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2756bedd-494a-54d5-9fc2-f245cf1e0eaf','eb8fed06-4bd6-5fce-a248-73cb28b1fcd5','mistake',3,'Lifting hips off the bench','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('84270359-b30e-549e-813a-1d9930450597','577bc835-2fab-5966-a447-75e1a1eb0638','step',1,'To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('97b0beed-273d-5da5-a8c1-c58140020be3','577bc835-2fab-5966-a447-75e1a1eb0638','step',2,'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9a0be217-e007-590a-b45b-74b405084bcf','577bc835-2fab-5966-a447-75e1a1eb0638','step',3,'Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0d7f5889-436d-5542-96c4-9bdcb4f40f2d','577bc835-2fab-5966-a447-75e1a1eb0638','step',4,'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0670bf8d-2476-54be-81fb-b56c4f78c736','577bc835-2fab-5966-a447-75e1a1eb0638','step',5,'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ab9a9592-2f65-5358-929e-353e0b1b40bb','577bc835-2fab-5966-a447-75e1a1eb0638','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('94b7f2d9-76bd-57d3-84dd-8ecf37562272','577bc835-2fab-5966-a447-75e1a1eb0638','cue',1,'Brace your core before you descend','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7659cd1b-29db-57b0-9628-ed326d20ed87','577bc835-2fab-5966-a447-75e1a1eb0638','cue',2,'Knees track over your toes','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('188d3322-54ff-52b8-820b-ad7e18fbac80','577bc835-2fab-5966-a447-75e1a1eb0638','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0a3e89fe-96d2-566e-9c6b-78a63aa93f48','577bc835-2fab-5966-a447-75e1a1eb0638','mistake',1,'Knees caving inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4565870-959b-50bd-90ed-119037c3c267','577bc835-2fab-5966-a447-75e1a1eb0638','mistake',2,'Heels lifting off the floor','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f793cce1-0c0e-54fd-96cb-17316c8078f8','577bc835-2fab-5966-a447-75e1a1eb0638','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('accf0fe8-0c80-5154-a80e-b957c9de6d67','92da84d7-f61c-50a9-9bf3-de77fd6bc346','step',1,'Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('46d622f6-3703-527a-8155-c25bc5aa0dbc','92da84d7-f61c-50a9-9bf3-de77fd6bc346','step',2,'As you breathe in, come down slowly until you feel the bar on your middle chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eae45c10-65a7-59d9-9860-7dd76989922e','92da84d7-f61c-50a9-9bf3-de77fd6bc346','step',3,'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('522139e0-505d-57ee-96d7-9a01fa79fa7a','92da84d7-f61c-50a9-9bf3-de77fd6bc346','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b5a486e6-c850-5a83-a052-c75481704a90','92da84d7-f61c-50a9-9bf3-de77fd6bc346','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
