INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a8208149-eb95-5d17-b9e2-05f5b93a7b00','ca2866bc-03bd-5488-b364-d520be21090c','step',1,'Hold the wrist roller with your arms straight out in front.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('833356b2-0638-564d-82fb-87d8547ee9e7','ca2866bc-03bd-5488-b364-d520be21090c','step',2,'Roll the cord up by turning your wrists one hand at a time.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ca5321e-5806-5b18-87e8-0925524f5113','ca2866bc-03bd-5488-b364-d520be21090c','step',3,'Reverse the motion slowly to lower the weight.','en','ai_authored:fitbud_curated');
