INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('127ac2cd-0427-5c46-812e-7528dedd489a','3e417876-dbb2-5fff-85de-aed1b1ba70da','step',1,'Hang from the pull-up bar with an underhand grip, hands about shoulder-width apart.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('10bed9c8-04b8-555c-ab2d-df4e313fc6bc','3e417876-dbb2-5fff-85de-aed1b1ba70da','step',2,'Pull your chest toward the bar until your chin is over it.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('03cb441b-0448-55a9-a81d-0fcac83c8e25','3e417876-dbb2-5fff-85de-aed1b1ba70da','step',3,'Hold the top and raise your straight legs until they are level with your hips.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('90a8b0ea-2492-5641-863b-5bbe26b1ca89','3e417876-dbb2-5fff-85de-aed1b1ba70da','step',4,'Lower your legs, then lower yourself under control to a full hang.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1a09ffd5-ed14-5ace-9fda-f33cfd34980d','3e417876-dbb2-5fff-85de-aed1b1ba70da','cue',1,'Start each rep by pulling the shoulder blades down','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('26460aeb-3e02-59a8-bc37-82edd4194e5b','3e417876-dbb2-5fff-85de-aed1b1ba70da','cue',2,'Drive elbows toward your ribs','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('69ecd673-2899-53eb-b431-f33e28d29927','3e417876-dbb2-5fff-85de-aed1b1ba70da','cue',3,'Control the way down to a full hang/stretch','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c14dff11-d546-5ed6-b540-ee4f22407a5b','3e417876-dbb2-5fff-85de-aed1b1ba70da','mistake',1,'Kipping or swinging','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8502c3dc-b27c-5d99-a3fd-c5167a73ea1d','3e417876-dbb2-5fff-85de-aed1b1ba70da','mistake',2,'Half reps','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be574906-508f-5f28-bc28-5f029def74ef','3e417876-dbb2-5fff-85de-aed1b1ba70da','mistake',3,'Pulling behind the neck','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0f7b8983-7cfb-550d-9a41-415bda0ba948','17c2e0f5-2975-596e-a3c0-1a9ac6814c18','step',1,'With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('67abc3b6-5918-5327-891c-7c01989a9150','17c2e0f5-2975-596e-a3c0-1a9ac6814c18','step',2,'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a2b56808-1817-5633-ad99-4c72da0d5f1c','17c2e0f5-2975-596e-a3c0-1a9ac6814c18','step',3,'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ebb9a2ef-4f6a-54f6-8f74-a3556c136a30','17c2e0f5-2975-596e-a3c0-1a9ac6814c18','step',4,'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ad8318ec-5cfc-5b97-a3d5-883a75dc9ab5','17c2e0f5-2975-596e-a3c0-1a9ac6814c18','step',5,'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cdfcc066-9581-5e9c-9e8f-1bc31c395086','17c2e0f5-2975-596e-a3c0-1a9ac6814c18','cue',1,'Drive explosively with the legs/hips','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('76138765-0fc6-5bff-954c-2464e1fcd275','17c2e0f5-2975-596e-a3c0-1a9ac6814c18','cue',2,'Keep the load close','en','ai_derived:pattern');
