INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a5905dca-42dc-552c-a0ff-655bbb714a83','9f7c3cc0-3e23-51a9-aa85-86ff7eb7ea42','step',4,'Return your arms back to the starting position as you squeeze your chest muscles and breathe out.','en','source:free_exercise_db');
