INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d99d955b-a613-50f8-9859-175d3c8e000c','65618d9c-1129-5457-988a-6c9b67a0e876','step',3,'Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6d6124c9-3506-5752-a99a-8c255e92ce56','65618d9c-1129-5457-988a-6c9b67a0e876','step',4,'Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.','en','source:free_exercise_db');
