INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('26b71e70-15ea-5d50-980f-5c56ee52dd3e','b60bd338-1b50-5da1-a7ab-f88cd0ae0797','step',2,'Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other).','en','source:wger+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f21e6f81-195a-5e00-8399-23bc50f371d3','b60bd338-1b50-5da1-a7ab-f88cd0ae0797','step',3,'Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest.','en','source:wger+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('300ab938-e862-5032-b282-75a9c6db1267','b60bd338-1b50-5da1-a7ab-f88cd0ae0797','step',4,'Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps.','en','source:wger+fitbud_curated_edit');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f3243b63-9287-5022-8338-3d458e75a57e','b60bd338-1b50-5da1-a7ab-f88cd0ae0797','step',5,'Forcefully extend your elbows to return the dumbbells to the starting position. Focus on "pushing your pinkies toward the sky" to maximize triceps engagement.','en','source:wger+fitbud_curated_edit');
