INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f1db9852-ddf9-5007-8464-a0cefc9b6b1e','ff0b35f7-b66a-5e2a-ae8c-932cc1eba4bf','step',5,'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. There is no motion that happens at the elbow joint.','en','source:free_exercise_db');
