INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7b19fecd-9370-58c7-baa4-1715925ac57d','5c609ffa-771c-59bb-9be1-6af54025dfa2','step',1,'Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d9edb73a-d262-5631-a8fb-8751f772454f','5c609ffa-771c-59bb-9be1-6af54025dfa2','step',2,'Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e47a9fff-0153-56d4-8750-f6b9bfc937cf','5c609ffa-771c-59bb-9be1-6af54025dfa2','step',3,'Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('52f21f4e-3347-5c9c-9b7d-0746cb483c49','5c609ffa-771c-59bb-9be1-6af54025dfa2','step',4,'Slowly lower down to the starting position as you inhale.','en','source:free_exercise_db');
