INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6565eb76-d3be-53b1-914b-ab5961574862','7be1aa92-65c8-5a39-a831-827aeed30b8e','step',1,'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fe150e25-0496-51c0-a9f7-fcc9f942ea4e','7be1aa92-65c8-5a39-a831-827aeed30b8e','step',2,'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('34f27fc9-007e-51c7-b760-64299172c426','7be1aa92-65c8-5a39-a831-827aeed30b8e','step',3,'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('af68c978-4bff-56f7-b99e-9c8abe58c860','7be1aa92-65c8-5a39-a831-827aeed30b8e','step',4,'Receive the bar with the arms locked out overhead.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37c5e258-a692-5dee-a8b9-b180c6cdd639','7be1aa92-65c8-5a39-a831-827aeed30b8e','step',5,'Return to a standing position.','en','source:free_exercise_db');
