INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8a98a566-ba68-56f2-b970-689080597f98','ffecc786-26cc-5e0a-ac4e-bd819850f396','step',1,'Set the bar on your upper back with bands from the top of the rack taking some weight at the bottom.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('91af6851-a37e-5b6e-a429-e578aff030be','ffecc786-26cc-5e0a-ac4e-bd819850f396','step',2,'Set your feet about shoulder-width apart, toes slightly out.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7d3162b-9797-50ad-95c1-588e708fc0c9','ffecc786-26cc-5e0a-ac4e-bd819850f396','step',3,'Brace your core and sit your hips down and back, knees tracking over your toes, until your thighs are about parallel.','en','ai_authored:fitbud_curated');
