INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8d043296-efb6-501e-9e1b-ba4edffa8c8f','ffecc786-26cc-5e0a-ac4e-bd819850f396','mistake',3,'Rounding the lower back at the bottom','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f8fe4dd7-5efa-5a08-892a-20bf3b673053','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','step',1,'Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f603b76a-8018-5b67-b78e-fe7a08fd3e3e','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','step',2,'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5cc01fae-4bdb-5503-a586-4bbbdd3feb2e','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','step',3,'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('29bca962-7d2f-5b57-acf9-a5fc9d91ddc7','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','step',4,'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9aed70b-7b00-55cf-90b3-15a09e31ac4d','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','cue',1,'Brace your core before you descend','en','ai_derived:pattern');
