INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8de5d228-92b9-5565-9fbf-77f6424c7c73','a0534253-45ad-5077-9a29-d8d38ddcce97','step',1,'Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1da39ea4-936b-549f-ba06-c3a2b7fa150c','a0534253-45ad-5077-9a29-d8d38ddcce97','step',2,'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d269ee6d-c644-5312-be60-a4ddde72204d','a0534253-45ad-5077-9a29-d8d38ddcce97','step',3,'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c24f0fc8-c1d9-5c51-9ca6-4d65d90e9dca','a0534253-45ad-5077-9a29-d8d38ddcce97','step',4,'After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d03bef54-973a-5d08-9423-480edff719bf','a0534253-45ad-5077-9a29-d8d38ddcce97','step',5,'Lower the bar by bending at the hips and guiding it to the floor.','en','source:free_exercise_db');
