INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('43f589f9-bfbd-5026-96bd-42356cb569e8','551e8158-e857-5bf0-b14f-830666c27fc2','step',1,'Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e68e6d2d-1e85-5ccb-9950-b15e1d30a964','551e8158-e857-5bf0-b14f-830666c27fc2','step',2,'Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ad8d76ad-84e1-5c89-a185-ca7074766011','551e8158-e857-5bf0-b14f-830666c27fc2','step',3,'Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f39394d5-7c5e-55cf-aa76-392b30df3246','551e8158-e857-5bf0-b14f-830666c27fc2','step',4,'While keeping your feet and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go. Stretching or moving too far can cause an injury to occur.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0ab758ce-bd60-58f0-9781-dd6770b984df','551e8158-e857-5bf0-b14f-830666c27fc2','step',5,'Remember to breathe out while twisting your body to the side and in when moving back to the starting position.','en','source:free_exercise_db');
