INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('44c8649e-5b95-58e2-9346-b40c8672f6bc','015c484b-1ddf-57e7-9605-d79d69e19144','step',2,'Rotate the palms of the hands so that they are facing your torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1ed096a1-4c3a-5039-8985-016c3d87d4c2','015c484b-1ddf-57e7-9605-d79d69e19144','step',3,'While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('071c9f2c-da83-5879-9a14-ae7c7d8333cb','015c484b-1ddf-57e7-9605-d79d69e19144','step',4,'Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.','en','source:free_exercise_db');
