INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('de62a8a9-c2f3-57e5-a5d2-5253a60cad26','19e7b2a7-80e1-5189-a766-7b3fd03ef82d','step',2,'Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.','en','source:wger');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('689c4cf3-334d-54cf-9fa6-ebae1e9c2c3f','19e7b2a7-80e1-5189-a766-7b3fd03ef82d','step',3,'Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.','en','source:wger');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('75100f46-148d-55a4-ae99-d1cfd7874912','19e7b2a7-80e1-5189-a766-7b3fd03ef82d','step',4,'Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.','en','source:wger');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b16b0dff-8379-572e-8f96-eeb03e0c7c44','19e7b2a7-80e1-5189-a766-7b3fd03ef82d','step',5,'After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg.','en','source:wger');
