INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2088cfb2-c21a-599f-ae6a-529ccde36d96','a05f87e6-b02d-51ee-9b5d-209cd80b43b4','step',1,'Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('51b51fb0-fe6f-5bc0-8d7b-8783c8bdb524','a05f87e6-b02d-51ee-9b5d-209cd80b43b4','step',2,'As you breathe in, come down slowly until you feel the bar on your middle chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('afebeb49-73cd-5a0c-8743-7d37ac72fbe9','a05f87e6-b02d-51ee-9b5d-209cd80b43b4','step',3,'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('faa12824-c0d1-5c31-98a9-76d579097f28','a05f87e6-b02d-51ee-9b5d-209cd80b43b4','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fb3a75af-eadb-52d0-a934-a927069cffd3','a05f87e6-b02d-51ee-9b5d-209cd80b43b4','step',5,'When you are done, lock the bar back in the rack.','en','source:free_exercise_db');
