INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7a50ca1-7bba-582e-b972-86503bba0bdf','25897c84-c976-5501-a742-c695c1d8968c','mistake',3,'Short range of motion','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('44101bd6-9b74-561c-b6e1-2ec7b658e08f','725831c3-5530-5085-8e98-104c9d570873','step',1,'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1e482c39-235a-5819-9ee6-03efe445fcec','725831c3-5530-5085-8e98-104c9d570873','step',2,'Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3659ef2e-f736-541b-ae13-a2e31d5238ff','725831c3-5530-5085-8e98-104c9d570873','step',3,'Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('11605877-c323-581c-972b-66d1ab00f7b1','725831c3-5530-5085-8e98-104c9d570873','step',4,'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4b390477-ca94-5e78-a504-9ab87ba54718','725831c3-5530-5085-8e98-104c9d570873','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bb12d62d-fbaa-5abf-ad14-e67c91cc5d2a','725831c3-5530-5085-8e98-104c9d570873','cue',1,'Lead with the elbows','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c0a46119-413b-5157-b78c-d708412e33cc','725831c3-5530-5085-8e98-104c9d570873','cue',2,'Control the lowering','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3d4b43a1-b14d-5d5f-8ebb-b5314f3b41ce','725831c3-5530-5085-8e98-104c9d570873','cue',3,'Keep shoulders away from ears','en','ai_derived:pattern');
