INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0f604cfe-0494-5236-a16c-745cf9e7f951','83071d6e-5d91-5e76-988e-6c61e3e9f479','step',1,'Lie back on a flat bench with your eyes under the bar.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8c5ec33c-844c-5ef5-abb5-2cccdda265cb','83071d6e-5d91-5e76-988e-6c61e3e9f479','step',2,'Grip the bar with your hands clearly wider than shoulder-width, set your shoulder blades back and down, and unhook it to straight arms over your shoulders.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('70a0a4ef-1c8f-57e0-84d7-cc8b5fd88680','83071d6e-5d91-5e76-988e-6c61e3e9f479','step',3,'Lower the bar under control to your mid chest, elbows at about 45-70 degrees from your body.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8dd56cc8-b2d2-5421-a9b2-8ac19be8a7fb','83071d6e-5d91-5e76-988e-6c61e3e9f479','step',4,'Press the bar back up to straight arms, keeping your feet planted and your upper back tight.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b560a506-ec86-57b8-9808-86e6b401ebbb','83071d6e-5d91-5e76-988e-6c61e3e9f479','step',5,'Rack the bar carefully when the set is done.','en','ai_authored:fitbud_curated');
