INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea37fbc1-9d86-56b1-9b44-f91ace683497','83071d6e-5d91-5e76-988e-6c61e3e9f479','cue',2,'Wrists stacked over elbows','en','ai_derived:pattern');
