INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8dfe1aa5-153c-53be-b1bd-95a2dd229557','55b83608-b2e6-57f6-a02d-b245024e179d','step',1,'Hold the barbell in the crooks of your elbows close to your body.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3b136ac4-a101-5809-9448-3822a747f49a','55b83608-b2e6-57f6-a02d-b245024e179d','step',2,'Set your feet about shoulder-width apart, toes slightly out.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('109050a4-525d-5160-a060-6964e11e149f','55b83608-b2e6-57f6-a02d-b245024e179d','step',3,'Brace your core and sit your hips down and back, knees tracking over your toes, until your thighs are about parallel.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc0ba036-c077-5b48-97e6-c1734902c6df','55b83608-b2e6-57f6-a02d-b245024e179d','step',4,'Drive through your whole foot to stand back up tall.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('928a86af-36cb-5d38-9def-ee32c1277934','55b83608-b2e6-57f6-a02d-b245024e179d','cue',1,'Brace your core before you descend','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('059d7afc-d5df-5207-b9e8-e3aaa6f47843','55b83608-b2e6-57f6-a02d-b245024e179d','cue',2,'Knees track over your toes','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ff877e8d-c0e0-5670-b490-7b5192450548','55b83608-b2e6-57f6-a02d-b245024e179d','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fd0ed282-b8b9-57f1-9b11-8a4a95355a23','55b83608-b2e6-57f6-a02d-b245024e179d','mistake',1,'Knees caving inward','en','ai_derived:pattern');
