INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('70993b4e-c753-5c46-8209-ee1e8b955fc3','55b83608-b2e6-57f6-a02d-b245024e179d','mistake',3,'Rounding the lower back at the bottom','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c0bc768e-f9d3-58bf-b21a-38b8a6267dab','636debea-2b2b-507c-8b81-f13be980e677','step',1,'Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('99b9e042-22e2-5a6e-b8be-da5c1a4c91c2','636debea-2b2b-507c-8b81-f13be980e677','step',2,'With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e0cd0d6a-9f7f-5753-84f3-a81e82c85d13','636debea-2b2b-507c-8b81-f13be980e677','step',3,'Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs. As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('edeadb1c-8d23-5054-aee9-c20fa8fd2084','636debea-2b2b-507c-8b81-f13be980e677','step',4,'Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('af5706cf-905f-59c8-b291-4aad56cbe3c7','636debea-2b2b-507c-8b81-f13be980e677','step',5,'Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a49b55ba-2089-5641-b0e3-1af1e7f6806e','636debea-2b2b-507c-8b81-f13be980e677','step',6,'Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('19a4ff4f-4eab-5a56-9ddb-db73595132b0','636debea-2b2b-507c-8b81-f13be980e677','cue',1,'Drive explosively with the legs/hips','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ed8667b2-7491-5238-940c-072fad6f1f73','636debea-2b2b-507c-8b81-f13be980e677','cue',2,'Keep the load close','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f7abd36a-6e88-5aad-87c9-9161d9d1165b','636debea-2b2b-507c-8b81-f13be980e677','cue',3,'Land or receive softly','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('053df046-de56-52a9-8494-8604754be9a7','636debea-2b2b-507c-8b81-f13be980e677','mistake',1,'Pulling early with the arms','en','ai_derived:pattern');
