INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('554fd550-ce54-58b9-898d-1c952aede73a','636debea-2b2b-507c-8b81-f13be980e677','mistake',3,'Doing these when fatigued','en','ai_derived:pattern');
