INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5ade0322-9cb9-5cd5-8a5e-6b69311da755','bd22281f-3124-5097-9a9c-63f1eac00a9d','step',1,'Get into a high plank with your hands just wider than your shoulders and your body in a straight line from head to heels.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4a04dcb9-998d-5478-b8bc-ea07ec9b3f46','bd22281f-3124-5097-9a9c-63f1eac00a9d','step',2,'Brace your core and bend your elbows to lower your chest toward the floor, keeping your elbows at about 45 degrees to your body.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7868418f-1d91-5c2d-9b36-b8b7df260be8','bd22281f-3124-5097-9a9c-63f1eac00a9d','step',3,'Push the floor away to straighten your arms, keeping your hips in line with your shoulders.','en','ai_authored:fitbud_curated');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d1c875f3-f0fd-5667-8c25-323c5fa73dd6','bd22281f-3124-5097-9a9c-63f1eac00a9d','step',4,'As you lower, bring one knee out toward the elbow on the same side, then switch sides on the next rep.','en','ai_authored:fitbud_curated');
