INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6ce5847b-3050-55cc-b830-adade8542fe9','5b1b8587-8286-58a4-82e1-c8a746cdeddb','mistake',3,'Doing these when fatigued','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('573f17d4-b446-5538-acfe-eddf4e9d3697','274f1711-991f-5e54-857a-1786772ad380','step',1,'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6f4e1b49-e99a-5737-b499-9c70de44431a','274f1711-991f-5e54-857a-1786772ad380','step',2,'Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0f935a48-2dc8-598d-92d3-0785ee704ba3','274f1711-991f-5e54-857a-1786772ad380','step',3,'In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0210d840-ab4c-5956-a99c-df82f86b7693','274f1711-991f-5e54-857a-1786772ad380','step',4,'Return to a standing position, bringing the feet together.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('275d031c-c612-532b-a577-766b718358b7','274f1711-991f-5e54-857a-1786772ad380','cue',1,'Drive explosively with the legs/hips','en','ai_derived:pattern');
