INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('671bcf68-9fed-5816-b96a-f26c316d762f','274f1711-991f-5e54-857a-1786772ad380','mistake',3,'Doing these when fatigued','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fda8cbc8-a524-5f63-8145-48867881243d','c996fd3e-8bc7-51de-a937-49195c3af9b1','step',1,'Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9c950c87-bce0-5261-ae99-1e1063208771','c996fd3e-8bc7-51de-a937-49195c3af9b1','step',2,'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b06c34de-a750-59c9-a520-21fed1f474c7','c996fd3e-8bc7-51de-a937-49195c3af9b1','step',3,'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d0041fa2-4c15-51a3-badc-97621afa6a9a','c996fd3e-8bc7-51de-a937-49195c3af9b1','step',4,'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62068306-6022-5c65-ad9f-5498321e7a44','c996fd3e-8bc7-51de-a937-49195c3af9b1','step',5,'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8b54b574-0b8a-5911-a592-9965cec2e576','c996fd3e-8bc7-51de-a937-49195c3af9b1','step',6,'Carefully return the weight to floor.','en','source:free_exercise_db');
