INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('452c1189-0949-5c52-8789-e423c5b1ee5e','3e445d6c-c03e-510f-909d-abc1042a63ad','step',2,'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6ecdc665-20e4-5351-8a0d-93d48dcb2e45','3e445d6c-c03e-510f-909d-abc1042a63ad','step',3,'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('038a6beb-774d-5275-b755-817a48c03131','3e445d6c-c03e-510f-909d-abc1042a63ad','step',4,'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','en','source:free_exercise_db');
